window.__CHRONICLE_CHUNK["wd-08"] = [
  {id:"world--4--p01",track:"world",year:4,yearApprox:false,dim:"politics",weight:2,title:"提比略退居罗德岛",summary:"皇位继承人无诏离京，远赴希腊自隐，继承之局一时悬空。",detail:{background:"马尔凯鲁斯与盖乌斯、卢奇乌斯相继早夭，提比略虽为养子，犹疑于见弃，与利维娅一系不睦。",process:"公元4年，提比略不待朝命自行东渡，居罗德岛，以研读哲学自处，谢绝公务；其母利维娅屡书恳请，皆不返。",impact:"奥古斯都同年转而收养阿格里帕·波斯图穆斯，继承安排再生变；公元14年帝崩，提比略乃回京承统。",figures:["提比略","奥古斯都","利维娅"],place:"罗德岛（今希腊罗德）",state:"罗马帝国",sources:["苏埃托尼乌斯《罗马皇帝传·提比略》","塔西佗《编年史》第一卷","维列乌斯·帕特库鲁斯《罗马史》第二卷"],tags:["朱里亚王朝","皇位继承","退隐"]},related:[]},
  {id:"world--9--e01",track:"world",year:9,yearApprox:true,dim:"economy",weight:2,title:"公民户口两数悬殊",summary:"塔西佗并列两次普查之数，学界谓口径本异。",detail:{background:"奥古斯都行公民普查三次，户口定贡赋与兵籍；条顿堡败后征兵愈急，丁口之数遂为时政所系。",process:"塔西佗记公元14年所报公民约四百十一万，又引前一次普查为九十三万七千，两数悬殊；《神圣奥古斯都行状》所录与前者相近。",impact:"近代学者多谓两数一取帝国公民之全、一取可行普查登记之人，未可径作户口减耗之证；惟兵源与税基之紧为实。",figures:["塔西佗","奥古斯都"],place:"罗马与意大利诸邦",state:"罗马帝国",sources:["塔西佗《编年史》第一卷","《神圣奥古斯都行状》第8节","《剑桥古代史》第二版第十卷"],tags:["户口","兵源","税基"]},related:[]},
  {id:"world--14--m01",track:"world",year:14,yearApprox:false,dim:"military",weight:3,title:"莱茵与潘诺尼亚军哗变",summary:"两路军团拒散抗役，新君初立即遇兵威之胁。",detail:{background:"奥古斯都新崩，边军久戍不撤，役重饷薄，遂以追念旧君、请求散归为名生乱。",process:"公元14年冬，下日耳曼诸军团先哗，劫持日耳曼尼库斯；潘诺尼亚军亦杀将据营。前者以补欠饷、增遗赠抚定，后者由德鲁苏斯翌年以援军与分化平之。",impact:"新君以金钱安边军，成此后帝与军队互市之例；塔西佗以为内战之兆实始于斯。",figures:["日耳曼尼库斯","德鲁苏斯","提比略"],place:"下日耳曼与潘诺尼亚军营（今科隆、维也纳一带）",state:"罗马帝国",sources:["塔西佗《编年史》第一卷","苏埃托尼乌斯《罗马皇帝传·提比略》","狄奥·卡西乌斯《罗马史》第五十七卷"],tags:["兵变","军团","边军"]},related:[]},
  {id:"world--14--i01",track:"world",year:14,yearApprox:false,dim:"institution",weight:3,title:"选举之权移于元老院",summary:"共和遗制的名位，自公民会议转手于父老之院。",detail:{background:"奥古斯都以恢复共和为号，留公民会议之名而行摄政之实；帝崩之际，新君须速定权宜之制。",process:"公元14年，提比略以元老院议决取代公民会议的选举与立法职能，执政官与行政长官之选改由元老院定之。",impact:"共和官制的外壳自此仅存名目，元老院渐为奉行内廷之意；二世纪后连此程序亦由军队与宫廷代行。",figures:["提比略"],place:"罗马",state:"罗马帝国",sources:["塔西佗《编年史》第一卷","苏埃托尼乌斯《罗马皇帝传·提比略》"],tags:["元老院","官制","皇权"]},related:[]},
  {id:"world--15--m01",track:"world",year:15,yearApprox:false,dim:"military",weight:2,title:"日耳曼尼库斯收还鹰旗",summary:"六年后罗马军重履条顿堡战场，敛骸祭葬。",detail:{background:"公元9年条顿堡林之败后，莱茵诸军久不出击；日耳曼尼库斯奉朝命整军北渡，以雪前耻。",process:"公元15年夏，军至条顿堡战场，收暴骨之骸次第葬之，复所失鹰旗，焚阿尔明尼乌斯之村邑；秋师还。",impact:"此役快意于一时而未能定日耳曼；翌年伊迪斯塔维索之战后，朝廷以久劳于外召还，遂以莱茵河为界。",figures:["日耳曼尼库斯","阿尔明尼乌斯"],place:"条顿堡林与威悉河间（今德国西北部）",state:"罗马帝国",sources:["塔西佗《编年史》第一卷、第二卷","狄奥·卡西乌斯《罗马史》第五十六卷"],tags:["鹰旗","日耳曼","边界"]},related:[]},
  {id:"world--17--p01",track:"world",year:17,yearApprox:false,dim:"politics",weight:3,title:"卡帕多西亚内属为行省",summary:"附庸王被召受审而废，东方屏藩之制始摇。",detail:{background:"阿凯劳斯自奥古斯都时受封卡帕多西亚诸地，久有骑墙于帕提亚之疑；罗马向以附庸王为东方缓冲。",process:"公元17年，阿凯劳斯被召至罗马受审，旋流于高卢之维埃纳，其地议为行省，以骑士品之长官统之。",impact:"罗马前线自托罗斯山以北推进，与帕提亚势力直接相接；附庸王国缓冲之制在帝国东方渐废。",figures:["阿凯劳斯","提比略"],place:"卡帕多西亚（今土耳其中部开塞利一带）",state:"罗马帝国",sources:["塔西佗《编年史》第二卷","约瑟夫斯《犹太古史》第十八卷","狄奥·卡西乌斯《罗马史》第五十七卷"],tags:["行省","附庸王","东方"]},related:[]},
  {id:"world--19--f01",track:"world",year:19,yearApprox:false,dim:"figure",weight:3,title:"日耳曼尼库斯卒于安条克",summary:"东方督办三十四岁客死，铜表议决议今犹存。",detail:{background:"日耳曼尼库斯平莱茵与东方之军，奉命按行东方诸省，与叙利亚长官格涅乌斯·皮索积不相能。",process:"公元19年秋，病于安条克而卒，年三十四；遗体归罗马，葬于马塞鲁斯陵。元老院立案究皮索，皮索兵败见杀。",impact:"记此事之元老院决议铜表出土于贝提卡，为研究元首与元老院互动之最要铭刻；其诸子中卡利古拉终承帝位。",figures:["日耳曼尼库斯","皮索","小安东尼娅"],place:"安条克（今土耳其安塔基亚）",state:"罗马帝国",sources:["塔西佗《编年史》第二卷","《论格涅乌斯·皮索之元老院决议》铜表（CIL II² 685）","《夏拉铜表》与《希班铜表》所载元老院决议"],tags:["铭刻","皇族","东方行省"]},related:[]},
  {id:"world--26--p01",track:"world",year:26,yearApprox:false,dim:"politics",weight:3,title:"提比略退居卡普里岛",summary:"君离京垂十余年，政务尽委近卫军长官。",detail:{background:"日耳曼尼库斯与德鲁苏斯先后死，老皇帝倦于朝议，亦欲避母妻之相逼。",process:"公元26年起，提比略退处卡普里（今那不勒斯湾卡普里岛），遣使持函上元老院，军政钱谷一决于近卫军长官塞亚努斯。",impact:"元首之威与近侍之权相为表里，告密之狱大炽；塔西佗《编年史》第四、五卷所记大半出于是期间。",figures:["提比略","塞亚努斯"],place:"卡普里岛与罗马",state:"罗马帝国",sources:["塔西佗《编年史》第四卷","苏埃托尼乌斯《罗马皇帝传·提比略》","斯佩隆加离宫遗址发掘报告"],tags:["隐退","近卫军","权臣"]},related:[]},
  {id:"world--31--p01",track:"world",year:31,yearApprox:false,dim:"politics",weight:4,title:"塞亚努斯伏诛",summary:"握兵柄十余年之近卫军长官，一日就戮于阙下。",detail:{background:"塞亚努斯兼领诸军之营，排日耳曼尼库斯诸子，与德鲁苏斯之妻私通，权与人主相埒。",process:"公元31年10月，提比略发密函于元老院，先夺其军职，旋以反状收系，杀之于罗慕路斯坡下，暴尸台伯河；其子女亦遇戮。",impact:"此后近卫军虽盛，不复有专任一臣之局；朝廷追理余党数年，塔西佗记株连之众不绝于牍。",figures:["塞亚努斯","提比略","奈维乌斯·马克罗"],place:"罗马",state:"罗马帝国",sources:["塔西佗《编年史》第五、六卷","苏埃托尼乌斯《罗马皇帝传·提比略》","狄奥·卡西乌斯《罗马史》第五十八卷"],tags:["权臣","近卫军","清洗"]},related:[]},
  {id:"world--33--e01",track:"world",year:33,yearApprox:false,dim:"economy",weight:2,title:"罗马信用之荒",summary:"现钱忽不可得，田宅之价随落，朝廷出御库以济。",detail:{background:"旧制放债者须以资财置意大利田产；塞亚努斯党羽伏诛后，追缴与告发并发，现钱尽为所敛。",process:"公元33年，罗马现钱奇贵，任裁判官者各须三百二十万塞斯特斯而无从得。提比略出御库金一亿，听以田宅为质，三年无息，其势乃定。",impact:"此为古代记述中少见的以国库贷款止信用收缩之例；塔西佗所记银根之紧，亦见意大利地产之滞。",figures:["提比略"],place:"罗马与意大利",state:"罗马帝国",sources:["塔西佗《编年史》第六卷","狄奥·卡西乌斯《罗马史》第五十八卷"],tags:["信用","土地","国库"]},related:[]},
  {id:"world--37--p01",track:"world",year:37,yearApprox:false,dim:"politics",weight:3,title:"卡利古拉即位",summary:"军与宫廷共奉新君，初行宽政，未几而暴。",detail:{background:"提比略崩于米森，近卫军长官马克罗与日耳曼尼库斯之女协谋，奉其遗孤继立。",process:"公元37年3月，盖乌斯·凯撒（军中号卡利古拉）入罗马，元老院即日请之；初赦囚、减苛礼、许集会，民以为新世。",impact:"同年秋大病，此后诛戮无度；对不列颠之虚张、东方庙像之议，皆起于亲政之后，君与元老院之信遂裂。",figures:["卡利古拉","马克罗","小安东尼娅"],place:"罗马与米森（今意大利米塞罗）",state:"罗马帝国",sources:["苏埃托尼乌斯《罗马皇帝传·卡利古拉》","菲洛《论出使加约》","约瑟夫斯《犹太古史》第十八、十九卷"],tags:["即位","近卫军","朱里亚王朝"]},related:[]},
  {id:"world--41--p01",track:"world",year:41,yearApprox:false,dim:"politics",weight:4,title:"克劳狄为近卫军所拥立",summary:"帝室惟余蹇涩之亲王，军士于幕后得之而奉焉。",detail:{background:"卡利古拉遇弑，元老院有议复共和者，诸党竞立而未定，宫闱与府库一时俱乱。",process:"公元41年1月，军士于宫殿幕后得克劳狄，即营中奉为君；元老院迫于兵势追认，其初犹假辞于共和之名。",impact:"帝位之得失决于营中，开此后拥立为市之例；克劳狄以释奴分掌书札、财谷与讼狱，元首之政内移。",figures:["克劳狄","卡西乌斯·凯瑞亚"],place:"罗马",state:"罗马帝国",sources:["苏埃托尼乌斯《罗马皇帝传·克劳狄乌斯》","约瑟夫斯《犹太古史》第十九卷","狄奥·卡西乌斯《罗马史》第六十卷"],tags:["近卫军","即位","释奴"]},related:[]},
  {id:"world--46--i01",track:"world",year:46,yearApprox:false,dim:"institution",weight:2,title:"克劳狄致亚历山大城书",summary:"纸草存皇帝公文之原件，见大城两民相争之状。",detail:{background:"亚历山大城诸族素以会堂、公民籍与演艺之席相争，卡利古拉末年已有流血。",process:"公元46年10月，克劳狄以书晓谕该城：禁其不复遣使于朝，戒犹太人勿假丧事之名生事，申明城邦旧规而责其安守。",impact:"此书为现存最完整之皇帝致城邦公文原件之一，见朝廷对东方大城抚压并行之处；其条流亦为行政史要料。",figures:["克劳狄"],place:"埃及亚历山大城",state:"罗马帝国",sources:["伦敦纸草 P.Lond. 1912 抄本","约瑟夫斯《犹太古史》第十九、二十卷","斯马尔乌德辑《卡利古拉·克劳狄乌斯·尼禄书札诏令》"],tags:["纸草","行省治理","族群之争"]},related:[]},
  {id:"world--48--p01",track:"world",year:48,yearApprox:false,dim:"politics",weight:3,title:"玛萨琳娜伏诛",summary:"皇后于帝出外时再嫁，旋死而嗣局大改。",detail:{background:"玛萨琳娜倚近侍与释奴揽省政，纳新贵以固宠，朝命多出其门。",process:"公元48年，克劳狄闻其于帝幸奥斯提亚时与盖乌斯·西利乌斯成婚，遣释奴杀之；翌年娶侄女小安东尼娅。",impact:"克劳狄朝宫闱自此为阿格里皮纳所控，尼禄由是得嗣；塔西佗于《编年史》第十一、十二卷尽揭内廷之政。",figures:["玛萨琳娜","克劳狄","小安东尼娅"],place:"罗马（卢库鲁斯园）",state:"罗马帝国",sources:["塔西佗《编年史》第十一卷","苏埃托尼乌斯《罗马皇帝传·克劳狄乌斯》","狄奥·卡西乌斯《罗马史》第六十一卷"],tags:["宫廷","皇后","继承"]},related:[]},
  {id:"world--49--p01",track:"world",year:49,yearApprox:true,dim:"politics",weight:2,title:"罗马逐犹太居民",summary:"皇帝令犹太离京，教内争「基勒斯托」为之端。",detail:{background:"一世纪中叶罗马城犹太社群渐大，会堂之众与改宗者杂处，城市长官苦于弹压。",process:"公元49年前后，克劳狄诏犹太人群离罗马。苏埃托尼乌斯记其「因基勒斯托之煽动」而生乱，学界于此指何人或何事犹有两说。",impact:"《使徒行传》记亚居拉与百基拉由是离意而寓哥林多，早期传教之路线因之转移；尼禄即位后渐有还者。",figures:["克劳狄","亚居拉"],place:"罗马",state:"罗马帝国",sources:["苏埃托尼乌斯《罗马皇帝传·克劳狄乌斯》第25节","《新约·使徒行传》18章","狄奥·卡西乌斯《罗马史》第六十卷残篇"],tags:["犹太人","驱逐","罗马城"]},related:[]},
  {id:"world--54--p01",track:"world",year:54,yearApprox:false,dim:"politics",weight:3,title:"尼禄即位与辅政之始",summary:"近卫军奉十七岁之君，元老院受之而望治。",detail:{background:"克劳狄崩于公元54年10月，阿格里皮纳以其子尼禄先布列塔尼库斯得立，军与宫定策于顷刻。",process:"公元54年，尼禄为近卫军所奉，元老院即日授大权；初以塞涅卡、布鲁斯辅政，戒杀罚，听元老议事。",impact:"数年后杀布列塔尼库斯、逐塞涅卡，亲政之暴渐著；64年之火与68年高卢之叛，皆伏于此局。",figures:["尼禄","塞涅卡","布鲁斯","阿格里皮纳"],place:"罗马",state:"罗马帝国",sources:["塔西佗《编年史》第十二、十三卷","苏埃托尼乌斯《罗马皇帝传·尼禄》","尼禄朝钱币与铭文"],tags:["即位","辅政","朱里亚王朝"]},related:[]},
  {id:"world--57--p01",track:"world",year:57,yearApprox:false,dim:"politics",weight:2,title:"倭奴国献见于汉廷",summary:"建武中元二年，列邦使者西渡受印绶。",detail:{background:"一世纪中北九州诸邦渐相统合，乐浪郡为汉东通之门户，海上有商贾与译使往来。",process:"建武中元二年（公元57年），倭奴国使者赴洛阳朝贡，光武帝赐印绶；《后汉书》书其事并记其道里。",impact:"此为华籍所载日本列邦通使之始；1784年福冈志贺岛出土之金印，学界多谓即所赐之印，然其国地望犹有异说。",figures:["光武帝"],place:"倭奴国与洛阳（今福冈一带、河南洛阳）",state:"倭诸邦与东汉",sources:["《后汉书·东夷传》","「汉委奴国王」金印（福冈志贺岛出土）","近代金石与考古考订之文"],tags:["通使","金印","北九州"]},related:[]},
  {id:"world--61--m01",track:"world",year:61,yearApprox:true,dim:"military",weight:3,title:"布狄卡起事与两城之焚",summary:"附庸王之妻举诸部兵，焚三城而后败。",detail:{background:"爱西尼王普拉斯尤死，国遂内属，其妻布狄卡受辱，债券与征发相激。",process:"公元60或61年，布狄卡举诸部之兵，焚卡姆路劳努姆、伦狄尼恩与维鲁拉米恩，屠留守之吏民；据狄奥所记死者以万数，古典之数多夸。",impact:"保林努斯于威瑟斯河一役破之，诸部扰至翌年乃定；朝廷增军塞上，不列颠之税与军制为之一变。",figures:["布狄卡","苏埃托尼乌斯·保林努斯"],place:"不列颠东南（今科尔切斯特、伦敦一带）",state:"罗马帝国",sources:["塔西佗《编年史》第十四卷","狄奥·卡西乌斯《罗马史》第六十二卷","苏埃托尼乌斯《罗马皇帝传·尼禄》","伦敦城废墟层位考古报告"],tags:["起事","焚城","不列颠"]},related:[]},
  {id:"world--63--p01",track:"world",year:63,yearApprox:false,dim:"politics",weight:3,title:"朗戴西亚之盟与王冠之授",summary:"亚美尼亚得王而冠须受于罗马，东方暂宁。",detail:{background:"帕提亚以阿尔沙奇系人据亚美尼亚王位，科尔布洛两度东征未能定其争。",process:"公元63年，朗戴西亚围后议和：梯里达底仍治亚美尼亚，而王冠须受于罗马之君；66年其亲至罗马，尼禄于广场授之。",impact:"此约定亚美尼亚地位垂半世纪，为罗马与帕提亚间以礼仪存实利之例；幼发拉底上流之界由是粗定。",figures:["科尔布洛","梯里达底一世","尼禄"],place:"亚美尼亚朗戴西亚（今土耳其东部）",state:"罗马帝国与帕提亚",sources:["塔西佗《编年史》第十五、十六卷","苏埃托尼乌斯《罗马皇帝传·尼禄》","狄奥·卡西乌斯《罗马史》第六十二、六十三卷"],tags:["和约","亚美尼亚","帕提亚"]},related:[]},
  {id:"world--66--c01",track:"world",year:66,yearApprox:true,dim:"culture",weight:3,title:"库姆兰书卷之藏匿",summary:"旷野聚落弃书入穴，千九百年后残卷重出。",detail:{background:"死海西北岸之聚落有团体居守，抄经立规相承；犹太起事后罗马军分道入犹大旷野。",process:"约公元66至68年间，聚落之人将书卷入陶壑藏于野，其地遂弃；诸抄本最终封存之年代，以古文字学与碳十四推之，说尚未一。",impact:"1947年后十一处窟穴相继发见，残片数千，为第二圣殿期犹太教与经本文字传受之最要实证。",figures:["佚名抄经者"],place:"死海西北岸库姆兰（今约旦河西岸）",state:"犹大与犹太诸团",sources:["库姆兰遗址发掘报告（1952—1956 年刊布）","《死海古卷》校勘丛刊","老普林尼《自然史》第五卷"],tags:["死海文书","抄本","旷野团体"]},related:[]},
  {id:"world--67--m01",track:"world",year:67,yearApprox:false,dim:"military",weight:3,title:"罗马军定加利利",summary:"两军团与辅兵北入，约塔帕塔经四十七日而溃。",detail:{background:"耶路撒冷起义诸分据边界，加里利亚之约塔帕塔当其冲，韦士帕先受东方军之任。",process:"公元67年春，韦士帕先以数万众围约塔帕塔，凡四十七日陷其城，加利利诸邑相继降；据约瑟夫斯所记，其人被执而从军。",impact:"罗马得北境粮道与兵路，先定沿海与外围而后向耶路撒冷；约瑟夫斯随军所见，为是役最详之记。",figures:["韦士帕先","约瑟夫斯"],place:"加利利约塔帕塔（今以色列北部）",state:"罗马帝国",sources:["约瑟夫斯《犹太战记》第三卷","约瑟夫斯《人生》","塔西佗《历史》第五卷"],tags:["围城","犹太战争","加利利"]},related:[]},
  {id:"world--69--m01",track:"world",year:69,yearApprox:false,dim:"military",weight:3,title:"巴达维之乱与莱茵军之裂",summary:"四帝之年未已，莱茵左岸诸营与部族同叛。",detail:{background:"加尔巴诛莱茵军旧将，维提里乌斯称于科隆，军营之誓与辅兵部族之势相挟。",process:"公元69年冬，巴达维人齐维利斯与高卢诸部起兵，焚莱茵船队，破诺维萨苏姆等营；至70年冬，罗马遣塞瑞亚利斯以和议而乱平。",impact:"莱茵左岸数营徙于右岸，乌比人代居河边；罗马以部族分而制之，边军愈倚内战之兵。",figures:["齐维利斯","塞瑞亚利斯","维提里乌斯"],place:"下日耳曼莱茵两岸（今克桑滕、奈梅亨一带）",state:"罗马帝国",sources:["塔西佗《历史》第二至第四章","约瑟夫斯《犹太战记》第四卷","莱茵边镇（今克桑滕）考古报告"],tags:["巴达维","兵变","莱茵边界"]},related:[]},
  {id:"world--71--p01",track:"world",year:71,yearApprox:false,dim:"politics",weight:3,title:"犹太凯旋式与圣殿器之陈",summary:"父子同举凯旋，圣殿之金器舆而过市。",detail:{background:"耶路撒冷既陷，元老院为韦士帕先与提图斯议凯旋之礼，铸钱与刻门以纪。",process:"公元71年，二人自东方循凯旋之道入京，舆中载金桌、七枝灯与圣殿之器；钱背铸「犹太被虏」之铭。",impact:"提图斯拱门浮雕即写此仪，为凯旋图像之要例；犹太岁税改输朱庇特神庙，兵威与财赋并成帝国之标。",figures:["提图斯","韦士帕先"],place:"罗马凯旋门道",state:"罗马帝国",sources:["约瑟夫斯《犹太战记》第七卷","提图斯凯旋门浮雕","韦士帕先与提图斯朝钱币背文"],tags:["凯旋式","钱币","圣殿器"]},related:[]},
  {id:"world--74--m01",track:"world",year:74,yearApprox:true,dim:"military",weight:3,title:"马萨达之围",summary:"战争最后一寨，罗马垒坡道以升破城之车。",detail:{background:"圣殿既焚，据险之众犹守死海旁之马萨达，日扰沿海村邑；朝廷命西尔瓦总其军。",process:"公元73或74年，围山筑营八座，垒石坡以升炮台；及破壁入上，据约瑟夫斯所记山上九百六十人已先自尽，惟二妇五童匿水道得存。",impact:"此役为犹太战争之终；遗址于1963至1965年发掘，坡道、营垒与陶片之数至今为讨论之点。",figures:["西尔瓦","以利亚撒"],place:"马萨达（今以色列死海之滨）",state:"罗马帝国",sources:["约瑟夫斯《犹太战记》第七卷","马萨达遗址发掘报告（1963—1965）"],tags:["围城","奋夺党","考古"]},related:[]},
  {id:"world--75--a01",track:"world",year:75,yearApprox:true,dim:"art",weight:2,title:"韦士帕先和平神庙之成",summary:"以战所获筑新庙，珍画与圣器许人纵观。",detail:{background:"犹太战争与帝位之争所得金谷，议筑新庙以纪太平，并辟列廊为市朝之辅。",process:"约公元75年，和平神庙成：中庭立巨像，陈所得圣殿之器、奇画与名医之书，旁启长廊数里。",impact:"以战争之获公开陈设，为帝国都邑收藏之新制；老普林尼记其画目与值，庙庭后为文士讲论之所。",figures:["韦士帕先","老普林尼"],place:"罗马苏布拉区",state:"罗马帝国",sources:["苏埃托尼乌斯《罗马皇帝传·韦士帕先》","老普林尼《自然史》第三十六卷","和平神庙遗址发掘简报"],tags:["建筑","收藏","公共空间"]},related:[]},
  {id:"world--80--d01",track:"world",year:80,yearApprox:false,dim:"disaster",weight:3,title:"罗马大火与连年之疫",summary:"新帝即位之夏，火延六日，疫继之而谷贵。",detail:{background:"韦士帕先新崩，提图斯承统，国库方匮而海运之粮未继。",process:"公元80年，火起，延及斗兽场、万神祠与诸殿，凡六日乃熄；时疫并作，谷船覆于河口，尸以载运出城。",impact:"提图斯出御库之财葺城除害，减贫民粮直；苏埃托尼乌斯称其一日未闻举城之哭，以为帝德之最。",figures:["提图斯"],place:"罗马",state:"罗马帝国",sources:["苏埃托尼乌斯《罗马皇帝传·提图斯》","狄奥·卡西乌斯《罗马史》第六十六卷","帕拉蒂尼与斗兽场层位发掘报告"],tags:["火灾","瘟疫","罗马城"]},related:[]},
  {id:"world--83--m01",track:"world",year:83,yearApprox:false,dim:"military",weight:2,title:"卡提之役与边墙之筑",summary:"图密善北击卡提，墙堑渐连上游日耳曼诸营。",detail:{background:"上游日耳曼诸营与卡提人久相攻取；韦士帕以来边地内缩，屯戍与税田之界未定。",process:"公元83年，图密善自罗马亲出，破卡提，分其境为二区；其后数十年，墙堑自美因河续筑至内卡河，关塞与望楼相衔。",impact:"此以人工之界代自然之限，为日耳曼边墙之始；军镇既密，边地市井与窑冶随之而兴。",figures:["图密善"],place:"上游日耳曼（今美因河至内卡河间）",state:"罗马帝国",sources:["塔西佗《阿格里科拉》","苏埃托尼乌斯《罗马皇帝传·图密善》","上游日耳曼边墙历次勘察刊布"],tags:["边墙","日耳曼","屯戍"]},related:[]},
  {id:"world--96--i01",track:"world",year:96,yearApprox:false,dim:"institution",weight:2,title:"犹太岁税之厘正",summary:"新帝钱背铭「去其诬」，理前朝敛钱之滥。",detail:{background:"韦士帕先以犹太岁税归朱庇特神庙，图密善并察改宗者及其裔，讼吏因缘为利。",process:"公元96年尼瓦即位，罢此纠讦之弊，钱背铸「犹太税之诬已去」之铭；狄奥记其时富家之坐此者，财产多没。",impact:"此钱为古代财政纠滥之罕见实物；尼瓦并以废告密、省东方之费称，储嗣之局由是定。",figures:["尼瓦"],place:"罗马",state:"罗马帝国",sources:["尼瓦银币背文","苏埃托尼乌斯《罗马皇帝传·图密善》","狄奥·卡西乌斯《罗马史》第六十七卷"],tags:["财税","钱币","告密"]},related:[]},
  {id:"world--100--c01",track:"world",year:100,yearApprox:false,dim:"culture",weight:2,title:"普林尼《颂词》宣读于元老院",summary:"执政官谢表新君，辞虽谀而寄为政之鉴。",detail:{background:"图拉真初即位，以执政官例须于元老院陈谢；修辞之学与政务之书至此合流。",process:"公元100年9月，小普林尼在元老院宣读颂图拉真之辞，后增删寄友；其《书信集》十卷并论讲习、田庄之费与属吏之责。",impact:"此篇存元首与元老院相谕之礼辞样本，亦见二世纪初士人之出处；后世以「明君与暴君之分」读之。",figures:["小普林尼","图拉真"],place:"罗马",state:"罗马帝国",sources:["小普林尼《颂词》","小普林尼《书信集》","《剑桥拉丁文学史》"],tags:["修辞","元首制","书信"]},related:[]},
  {id:"world--105--m01",track:"world",year:105,yearApprox:false,dim:"military",weight:4,title:"第二次达契亚之役",summary:"浮桥再济多瑙河，王都北筑新军镇。",detail:{background:"初战请和后，达契亚王德刻巴卢斯复修寨垒、招亡命，多瑙河北之属民与盐田两争不已。",process:"公元105年，图拉真再济多瑙河进击，破其诸寨；围萨米泽杰图萨，翌年降之，分其地为行省，徙诸省之民实边。",impact:"达契亚自此为多瑙河北之省，金矿入御库；纪功柱之浮雕并写两役，为军制与工程史之图像要料。",figures:["图拉真","德刻巴卢斯"],place:"达契亚（今罗马尼亚特兰西瓦尼亚一带）",state:"罗马帝国",sources:["狄奥·卡西乌斯《罗马史》第六十八卷（后期摘要本）","图拉真纪功柱浮雕","达契亚军砖铭与金币"],tags:["达契亚","渡河","行省"]},related:[]},
  {id:"world--107--e01",track:"world",year:107,yearApprox:false,dim:"economy",weight:2,title:"达契亚金与百日之庆",summary:"新金入库，都行长日之斗宴与赐钱。",detail:{background:"两役所获金谷山积，图拉真议以饰都邑、赐民而犒军。",process:"公元107年之凯旋庆典，据狄奥所记凡一百二十三日，角士与禽兽以万数，又行赐钱与销欠之令。",impact:"其金又入市币，银币成色稍复；论坛、市场与诸水道之费并出于是，二世纪初之富庶以此为标。",figures:["图拉真"],place:"罗马",state:"罗马帝国",sources:["狄奥·卡西乌斯《罗马史》第六十八卷（后期摘要本）","图拉真论坛与市场遗址发掘报告","图拉真朝钱币"],tags:["凯旋","金币","宴赏"]},related:[]},
  {id:"world--108--c01",track:"world",year:108,yearApprox:true,dim:"culture",weight:3,title:"安条克主教系狱途中之七书",summary:"自安条克西解于罗马，沿途遗诸会七书。",detail:{background:"伊纳爵为安条克主教，其会内争仪礼与基督幻身之说，朝廷也禁私聚之教。",process:"约公元106至108年间，伊纳爵系狱西解，经士每拿、特罗亚、腓立比诸地，沿途致书七会，戒众人从一主教、勿杂异说。",impact:"此七书为二世纪初主教职分与「大公」之称最古之据；后世所增之长篇与伪札，校勘家辨为晚出。",figures:["伊纳爵","图拉真"],place:"安条克至罗马之道",state:"罗马帝国与东方诸教会",sources:["伊纳爵书信七篇之最短本（近代校勘本）","优西比乌《教会史》第三卷","《使徒教父文献》辑本"],tags:["主教制","书信","殉道"]},related:[]},
  {id:"world--114--p01",track:"world",year:114,yearApprox:true,dim:"politics",weight:3,title:"亚美尼亚废王为行省",summary:"东方附庸之王位忽废，前线越幼发拉底。",detail:{background:"自朗戴西亚盟后，亚美尼亚王位属帕提亚之家，罗马以冠礼存其上国之体。",process:"约公元113至114年，图拉真以其王不受朝命，废之，以其国为行省，遣骑士品之长官守要道。",impact:"罗马遂与米底亚、阿杜雷贝尼直接接界，和议之礼仪框架尽废；帕提亚更立其族人拒之，战端以开。",figures:["图拉真"],place:"亚美尼亚与卡帕多西亚",state:"罗马帝国",sources:["狄奥·卡西乌斯《罗马史》第六十八卷（后期摘要本）","优西比乌《编年史》亚美尼亚丧国条","东方行省军砖与界碑铭刻"],tags:["附庸王","行省","东方"]},related:[]},
  {id:"world--115--m01",track:"world",year:115,yearApprox:false,dim:"military",weight:3,title:"两河之间之进兵与置省",summary:"罗马军东取二水之间，附庸纳质而诸城起。",detail:{background:"亚美尼亚既废，图拉真分军南渡幼发拉底、东北取山地之国。",process:"公元115年，取尼西比斯与厄德萨，执附庸王而废之；旋置美索不达米亚等三行省，同年犹大与埃及诸地复起兵，商路与屯戍多毁。",impact:"罗马之界一时越底格里斯；然兵寡而叛服不常，哈德良立乃弃东方三省，还守幼发拉底。",figures:["图拉真","阿布加尔"],place:"美索不达米亚（今伊拉克北部、叙利亚东北）",state:"罗马帝国与帕提亚",sources:["狄奥·卡西乌斯《罗马史》第六十八卷（后期摘要本）","优西比乌《编年史》","厄德萨与尼西比斯之钱币"],tags:["进军","置省","两河"]},related:[]},
  {id:"world--116--x01",track:"world",year:116,yearApprox:true,dim:"explore",weight:3,title:"舟师东至波斯湾",summary:"皇帝乘桴入海，望印度之舶而叹年高。",detail:{background:"两河既定，图拉真欲循水军以东向，追亚历山大之迹。",process:"约公元116至117年，自底格里斯河乘舟抵海湾，于岸立碑纪之；闻商舶之远来，自叹年老不得亲至印度。",impact:"此为罗马兵锋与皇迹东伸之极；其后二百年间再无罗马皇帝至此，海上商道仍循旧航。",figures:["图拉真"],place:"底格里斯河入海之湾（今波斯湾头）",state:"罗马帝国",sources:["狄奥·卡西乌斯《罗马史》第六十八卷（后期摘要本）","优特罗皮乌斯《罗马志纲要》第八卷","奥勒利乌斯·维克多《诸帝志》"],tags:["远征","海湾","航路"]},related:[]},
  {id:"world--117--m01",track:"world",year:117,yearApprox:true,dim:"military",weight:2,title:"毛里塔尼亚之乱与将之罢",summary:"边民破屯聚，讨定之将旋以功高见忌。",detail:{background:"毛里塔尼亚廷吉塔纳边地之属民苦于戍卒与市易，东方战起后边备尤虚。",process:"约公元115至117年，诸部破边地屯聚，帅昆图斯讨之稍定；哈德良代立即召其军还，夺符节而罢其任。",impact:"此事见载于后世所传之帝纪与非洲军砖，为边州之兵将相疑之早例；非洲边政自此以抚为主。",figures:["昆图斯","哈德良"],place:"毛里塔尼亚边地（今摩洛哥北部）",state:"罗马帝国",sources:["《奥古斯塔史·哈德良传》","狄奥·卡西乌斯《罗马史》第六十八卷（后期摘要本）","摩洛哥北部罗马边镇考古报告"],tags:["边境","属民","将权"]},related:[]},
  {id:"world--122--p01",track:"world",year:122,yearApprox:true,dim:"politics",weight:4,title:"哈德良巡行诸省",summary:"君离都垂十二年，边军赋册城宪亲加按核。",detail:{background:"图拉真末年东方之土不可守；新君以定界练兵为本，不事远征。",process:"约公元121至125年间，先后巡行高卢、不列颠、西班牙、东方与非洲，驻节之处核军籍、定律令之式，许诸省筑庙铸钱。",impact:"帝国成为一巡回之朝所治，行省建制与军团屯所渐归画一；都邑之营造与希腊文艺亦因之大兴。",figures:["哈德良"],place:"帝国诸省（不列颠与东方为要）",state:"罗马帝国",sources:["《奥古斯塔史·哈德良传》","狄奥·卡西乌斯《罗马史》第六十九卷（后期摘要本）","哈德良巡行所铸行省钱币"],tags:["巡行","行省","边军"]},related:[]},
  {id:"world--130--p01",track:"world",year:130,yearApprox:true,dim:"politics",weight:4,title:"耶路撒冷别筑爱利亚城",summary:"旧邦另立新名之邑，上主之庙临圣殿之基。",detail:{background:"哈德良欲以罗马城制改作东方之都会，圣殿故址之上别起神庙，议者纷然。",process:"约公元130年，以殖民城之制建爱利亚加比托利纳，立卡皮托利之庙，居民多外来之兵户与吏，旧禁仍严。",impact:"此事与割礼之禁相激，遂为巴尔科赫巴起事之端；乱定后城名与庙制不改，犹太之民不得入。",figures:["哈德良"],place:"耶路撒冷（今以色列与巴勒斯坦交界）",state:"罗马帝国",sources:["狄奥·卡西乌斯《罗马史》第六十九卷（后期摘要本）","优西比乌《教会史》第四卷","耶路撒冷与爱利亚城考古报告"],tags:["建城","圣殿","行省"]},related:[]},
  {id:"world--131--i01",track:"world",year:131,yearApprox:true,dim:"institution",weight:3,title:"裁判官告示之定本",summary:"岁有新格之例既止，程式之法始有定书。",detail:{background:"裁判官之告示岁有更张，积为讼者所凭；法学之士久议其宜画一。",process:"约公元131年，哈德良命萨尔维乌斯·尤里亚努斯与诸法学士裁定旧告示为固定之本，后非奉君命或元老院之议不得改。",impact:"程式诉讼之框架自此稳定，裁判官之法成为帝国法律之骨干；六世纪之《学说汇纂》所辑体例尤赖于此。",figures:["尤里亚努斯","哈德良"],place:"罗马",state:"罗马帝国",sources:["优士丁尼《学说汇纂》第一卷（蓬波尼乌斯《手册》节文）","《罗马法学说源流汇编》","盖尤斯《法学阶梯》"],tags:["法律","告示","法学"]},related:[]},
  {id:"world--135--i01",track:"world",year:135,yearApprox:true,dim:"institution",weight:4,title:"犹太地改号叙利亚巴勒斯坦",summary:"乱定之后省易其名，故城之禁仍不加宽。",detail:{background:"巴尔科赫巴之乱历三年乃平，犹太地之会堂与宗族组织几于俱毁。",process:"约公元135年后，其省之号改为叙利亚巴勒斯坦，都会之名亦易；拉比之师亚基巴等殉难，故城禁犹太人入居。",impact:"省名沿用至拜占庭之世；会堂之学自犹大移至加利利，口传律法之编纂之议由是而启。",figures:["哈德良","亚基巴"],place:"犹太地与叙利亚巴勒斯坦行省",state:"罗马帝国",sources:["狄奥·卡西乌斯《罗马史》第六十九卷（后期摘要本）","《巴比伦塔木德》论哈德良与亚基巴诸条","犹大与加利利之骨瓮与碑铭"],tags:["省制","改名","会堂之学"]},related:[]},
  {id:"world--137--e01",track:"world",year:137,yearApprox:false,dim:"economy",weight:3,title:"帕尔米拉商市税则之刻",summary:"双语长刻条记货目与税率，见沙漠都市之富。",detail:{background:"帕尔米拉据幼发拉底与波斯湾商路之会，两帝国各取其税，城邦自治其市。",process:"公元137年所刻税则，以希腊与帕尔米拉两语并列，条记货目、等差与市吏之责，香、紫布与驼载之货各有率。",impact:"此为古代长途贸易税则最详之实刻，见商队都市与帝国财政之接榫；石今庋于北方之都之博物馆。",figures:["佚名市吏"],place:"帕尔米拉（今叙利亚中部）",state:"帕尔米拉城邦与罗马帝国",sources:["帕尔米拉税则双语铭刻（1882年出土）","帕尔米拉铭刻辑录","老普林尼《自然史》论其市邑"],tags:["商路","税则","双语铭刻"]},related:[]},
  {id:"world--138--p01",track:"world",year:138,yearApprox:false,dim:"politics",weight:4,title:"安敦尼庇护承统",summary:"以元老之身嗣大位，在位不出意大利。",detail:{background:"哈德良晚岁两嗣相继死，乃采安东尼努斯为嗣，并使二青年从其子之列。",process:"公元138年7月哈德良崩，安东尼努斯初辞而后受，元老院难其速定，帝以兵卫自随乃安；号曰庇护，在位二十三年不亲征。",impact:"此为元首制中以因循致富庶之世：兵事少而讼狱平，国帑有余；后世以其名目一世纪之治。",figures:["安敦尼庇护","哈德良","马尔库斯·奥勒利乌斯"],place:"罗马与意大利",state:"罗马帝国",sources:["《奥古斯塔史·安敦尼·庇护传》","狄奥·卡西乌斯《罗马史》第六十九卷（后期摘要本）","马尔库斯·奥勒利乌斯《沉思录》第一卷"],tags:["即位","养嗣","元老院"]},related:[]},
  {id:"world--144--c01",track:"world",year:144,yearApprox:true,dim:"culture",weight:4,title:"马西翁与罗马教会之绝",summary:"还其捐金而绝之，乃别立教会与经目。",detail:{background:"马西翁自本都至罗马，捐巨金于其会，其说以创造之神与至善之父为二。",process:"约公元144年，罗马教会还其金而绝之于席；马西翁乃立自有之会，定经目，删路加福音与保罗诸书为正本。",impact:"其宗东行至叙利亚与波斯，数百年不绝；教会关于「正典」与两约之界，多缘拒其说而速定。",figures:["马西翁"],place:"罗马与东方诸会",state:"罗马帝国与诸教会",sources:["特土良《驳马西翁》","爱任纽《反异端》第一卷","优西比乌《教会史》第四卷"],tags:["正典","教争","别立之会"]},related:[]},
  {id:"world--150--p01",track:"world",year:150,yearApprox:true,dim:"politics",weight:3,title:"贵霜迦腻色伽之纪年",summary:"币铭与塔铭各立其元，二世纪中印之枢。",detail:{background:"贵霜自丘就却以来并四翕侯之地，据阿姆河与印度河之间，为陆海商路之枢。",process:"迦腻色伽所立纪年，旧说系于公元120年或150年，近复有127年诸说；其在位之金币成色高，希腊、伊朗与佛氏之像并存。",impact:"其世为犍陀罗与秣菟罗艺事之盛期，北传之佛教与结集之传皆托其名；纪年不定，二世纪中印史遂多悬案。",figures:["迦腻色伽"],place:"贵霜（今阿富汗东北至印度北部）",state:"贵霜帝国",sources:["贵霜金币与铭文（白沙瓦至马图拉诸地出土）","《大唐西域记》所传迦腻色伽诸国","南传《大史》所记结集之传"],tags:["贵霜","纪年之争","钱币"]},related:[]},
  {id:"world--165--m01",track:"world",year:165,yearApprox:true,dim:"military",weight:3,title:"东方军取泰西封",summary:"两河之役报捷，王城之市随以被焚。",detail:{background:"帕提亚入亚美尼亚，罗马自卡帕多西亚与叙利亚两道报之，阿维狄乌斯·卡西乌斯总东方之军。",process:"约公元164至165年，罗马军破塞琉西亚与泰西封，焚其王之宫与市，所得珍货载以东还。",impact:"兵威震于两河而卒不能有其地；东归之军与商旅携疫以入帝国，遂启后十余年之大疫。",figures:["卡西乌斯","路奇乌斯·维鲁斯"],place:"美索不达米亚（今伊拉克巴格达南北）",state:"罗马帝国与帕提亚",sources:["狄奥·卡西乌斯《罗马史》第七十一卷（后期摘要本）","路奇亚诺斯《论史法》","塞琉西亚遗址发掘报告"],tags:["东征","焚城","疫源"]},related:[]},
  {id:"world--167--e01",track:"world",year:167,yearApprox:true,dim:"economy",weight:3,title:"疫归东方与军实之耗",summary:"凯旋之军携疾西入，行省户口与兵源并减。",detail:{background:"两河之役既毕，东归之兵与商旅续入小亚细亚、意大利与埃及，疫随以行。",process:"约公元165至167年间，诸省军营死者相属；埃及之地册与军籍表见其耗，朝廷乃以减角税、募隶户补军。",impact:"边军之额自此多以降俘与隶户充之；公元171年币银减其成色，军赏与粮直并涨，三世纪之弊多张本于此。",figures:["马尔库斯·奥勒利乌斯"],place:"罗马帝国东部诸省与意大利",state:"罗马帝国",sources:["狄奥·卡西乌斯《罗马史》第七十一卷（后期摘要本）","盖伦注希波克拉底《疫症篇》论是时之疾","埃及纸草户口与军籍表"],tags:["瘟疫","兵源","币质"]},related:[]},
  {id:"world--170--m01",track:"world",year:170,yearApprox:true,dim:"military",weight:4,title:"北界之溃与阿奎莱亚之警",summary:"多瑙防军东调，诸部连衡而入意大利北境。",detail:{background:"东方之役与大疫之后，多瑙河诸营抽兵实东方，北岸诸部遂连名内侵。",process:"约公元170年，玛可曼尼、查乌迪等破潘诺尼亚与诺里库姆之边，杀守将，入意大利北境，阿奎莱亚几不守，举城戒严。",impact:"马尔库斯由是亲驻边垂垂十年，以军府临多瑙河，新立两军团于北方；后世所谓边族内徙之渐，实始于是。",figures:["马尔库斯·奥勒利乌斯"],place:"多瑙河北岸与意大利东北",state:"罗马帝国",sources:["弗龙托书信（论伤亡与募兵）","狄奥·卡西乌斯《罗马史》第七十一卷（后期摘要本）","马尔库斯纪功柱浮雕"],tags:["玛可曼尼","多瑙河","内侵"]},related:[]},
  {id:"world--174--m01",track:"world",year:174,yearApprox:true,dim:"military",weight:2,title:"雷雨之传与北方之和",summary:"水尽之际忽有大雨，军以为天助而诸部请盟。",detail:{background:"玛可曼尼山地之役，罗马军渴匮不能战，质子与使议久之不定。",process:"约公元172至174年，军亟而大雨骤至，古典诸史多记此异，教中传言谓此出军中信徒之祷；旋遣使于诸王，质其子弟，北边得安数年。",impact:"后世以「雷雨之柱」图形此事，是时军中基督之众渐显于史册；北方之役既毕，朝廷始议河外设省。",figures:["马尔库斯·奥勒利乌斯"],place:"玛可曼尼之境（今捷克与斯洛伐克一带）",state:"罗马帝国",sources:["弗龙托书信","狄奥·卡西乌斯《罗马史》第七十一卷（后期摘要本）","罗马雷雨之柱与纪功柱浮雕"],tags:["纪异","和约","多瑙"]},related:[]},
  {id:"world--175--p01",track:"world",year:175,yearApprox:false,dim:"politics",weight:3,title:"卡西乌斯称于东方",summary:"讹言帝崩，东方四军拥其主帅；旬月而败。",detail:{background:"阿维狄乌斯·卡西乌斯以东征之功位望方隆，与宫廷之隙日甚，又素疑见忌。",process:"公元175年春，有以帝病殂之讹言至东方者，卡西乌斯遂称，埃及与东方诸省多应之；未几真耗既明，为其下所杀。",impact:"东方诸军之权自此分小，埃及之驻兵益多；朝廷之信尽移于军与近侍，边功与内变相倚，为三世纪之渐。",figures:["卡西乌斯","马尔库斯·奥勒利乌斯"],place:"叙利亚与埃及",state:"罗马帝国",sources:["《奥古斯塔史·马可传》","狄奥·卡西乌斯《罗马史》第七十一至七十二卷（后期摘要本）","埃及纸草年号改易之记"],tags:["僭位","讹言","东方军"]},related:[]},
  {id:"world--177--c01",track:"world",year:177,yearApprox:true,dim:"culture",weight:3,title:"爱任纽《反异端》之成",summary:"条诸说而折之以经统，教父之学始有巨编。",detail:{background:"小亚与高卢诸会多循华伦丁诸家之说，各立经解，众心以疑。",process:"约公元177至180年，士每拿波利卡普之门人、卢格杜努姆主教爱任纽撰《辨异端》凡五卷，以经之统序与使徒承继之说拒其秘解。",impact:"此书存二世纪末教会之论与诸家说之要目；其使徒统绪与归元之旨，为后世信理与释经之骨干。",figures:["爱任纽","华伦丁"],place:"卢格杜努姆（今法国里昂）",state:"罗马帝国与高卢诸教会",sources:["爱任纽《反异端》（近代校勘本）","优西比乌《教会史》第五卷","《拿戈玛第经集》所收诸篇"],tags:["神学","护教","灵知诸家"]},related:[]},
  {id:"world--180--i01",track:"world",year:180,yearApprox:true,dim:"institution",weight:3,title:"多瑙河外两省之议",summary:"北征既屡克，议即其地置省而徙诸部。",detail:{background:"北征诸部既数败请降，边地之治由守转理，河外之地始入版图之议。",process:"约公元175至180年，议以玛可曼尼与萨尔玛提亚之地为二行省，徙万口之众于其境，以军屯与王庭之质镇之；帝崩而议格。",impact:"此策若成，则多瑙界外世有行省；其不成也，北边复归守势，诸部复合，为后此百年边患之渐。",figures:["马尔库斯·奥勒利乌斯"],place:"多瑙河外（今匈牙利至斯洛伐克一带）",state:"罗马帝国",sources:["弗龙托书信","狄奥·卡西乌斯《罗马史》第七十一卷（后期摘要本）","《奥古斯塔史·马可传》"],tags:["行省议","多瑙河","内徙"]},related:[]},
  {id:"world--182--p01",track:"world",year:182,yearApprox:false,dim:"politics",weight:2,title:"克里安德之诛",summary:"近侍以军资自肥，因宫谋败露而伏诛。",detail:{background:"康茂德亲政后委务于近侍，克里安德以军饷与官爵为市，北军与宫廷皆出其门。",process:"公元182年，皇姊卢奇拉之谋不克，朝廷杀克里安德以塞众怨；自是帝益不亲政务，占卜与竞技之徒迭用事。",impact:"一人之诛不救朝纲，告讦与卖爵愈甚；十年之间宫闱再变，安东尼之统遂绝。",figures:["康茂德","克里安德","卢奇拉"],place:"罗马",state:"罗马帝国",sources:["狄奥·卡西乌斯《罗马史》第七十二卷（后期摘要本）","希罗狄安《罗马帝国史》第一卷","《奥古斯塔史·康茂德传》"],tags:["近侍","宫闱","卖爵"]},related:[]},
  {id:"world--186--c01",track:"world",year:186,yearApprox:true,dim:"culture",weight:1,title:"皇帝自装赫丘立",summary:"君以神人之服临场手击百兽，礼俗互易。",detail:{background:"康茂德倦于朝仪而好狩猎竞技，自比于神人之最有力者。",process:"约公元186年前后，帝以狮皮与棒立于圆形之场，自手击兽，又列于角士之名；其赏赐与场费皆出府库。",impact:"古典诸史同载其事，以为君体之亵；自是竞技之党与近侍迭秉权，至192年为阉者所弑。",figures:["康茂德"],place:"罗马圆形场",state:"罗马帝国",sources:["《奥古斯塔史·康茂德传》","狄奥·卡西乌斯《罗马史》第七十二至七十三卷（后期摘要本）","康茂德朝雕刻与钱币"],tags:["宫廷","竞技","神像"]},related:[]},
  {id:"world--190--i01",track:"world",year:190,yearApprox:true,dim:"institution",weight:2,title:"一岁多官与爵秩之滥",summary:"是岁除执政官二十余员，名器自此可市。",detail:{background:"康茂德不理政务，府库与铨叙并出其近侍之门，旧格浸坏。",process:"约公元190年，是岁所除执政官至二十余人，又增裁判官之额，讼狱与官位多以资取；史家并书其滥。",impact:"其制旋废，而官爵可市之例遂开；此后卖位与军赏相寻，为三世纪财政与爵秩之弊张本。",figures:["康茂德"],place:"罗马",state:"罗马帝国",sources:["《奥古斯塔史·康茂德传》","希罗狄安《罗马帝国史》第一卷","狄奥·卡西乌斯《罗马史》第七十三卷（后期摘要本）"],tags:["卖官","爵秩","元老院"]},related:[]},
  {id:"world--193--p01",track:"world",year:193,yearApprox:false,dim:"politics",weight:4,title:"珀提纳克斯之立与殒",summary:"元老之臣被拥八月，卒为禁卫所弑。",detail:{background:"康茂德遇弑于192年之末，元老院次日追认旧臣珀提纳克斯，军众已怀贰。",process:"公元193年1月，近卫军拥之即位，帝欲以新律绳其军、分其赏；三月二十八日，军士入宫弑之，并废其后人所立之号。",impact:"禁卫自此以弑君为常，未几且以帝位当众拍卖；塞维鲁自北方来，诛其首事而改其额制。",figures:["珀提纳克斯"],place:"罗马",state:"罗马帝国",sources:["希罗狄安《罗马帝国史》第二卷","《奥古斯塔史·珀提纳克斯传》","狄奥·卡西乌斯《罗马史》第七十四卷（后期摘要本）"],tags:["弑君","近卫军","即位"]},related:[]},
  {id:"world--194--m01",track:"world",year:194,yearApprox:true,dim:"military",weight:3,title:"拜占庭之围与东军之胜",summary:"内战相持两载，双城之守至食尽乃下。",detail:{background:"东方诸军奉尼格尔为君，拜占庭当其冲，且通消息于帕提亚。",process:"约公元193至196年，塞维鲁先破东方军于基齐库斯与伊苏斯，进围拜占庭，水陆合守，历二载城破而毁其墙与市。",impact:"拜占庭以附敌失其城与税籍，旋蒙恩复；塞维鲁因东征之劳大行军赏，边军之权尽归一姓。",figures:["塞维鲁","尼格尔"],place:"拜占庭（今土耳其伊斯坦布尔）",state:"罗马帝国",sources:["希罗狄安《罗马帝国史》第二至三卷","《奥古斯塔史·塞维鲁传》","伊斯坦布尔城墙与层位考古报告"],tags:["内战","围城","东方"]},related:[]},
  {id:"world--197--m01",track:"world",year:197,yearApprox:true,dim:"military",weight:3,title:"卢格杜努姆之役",summary:"两帝之军会于隆河之北，胜负决于东方之兵。",detail:{background:"塞维鲁既东还，不列颠与高卢之军奉阿尔比努斯为帝，意大利与北方于是并立。",process:"约公元197年2月，两军会战于卢格杜努姆之北，累日相持，塞维鲁几殆；会东方百战之军至，始大败其众，阿尔比努斯走死。",impact:"内战以东方之兵与厚赏而胜，自是军饷岁增、边镇多分，国库与兵额相牵，三世纪之势渐成。",figures:["塞维鲁","阿尔比努斯"],place:"卢格杜努姆（今法国里昂）",state:"罗马帝国",sources:["希罗狄安《罗马帝国史》第二至三卷","狄奥·卡西乌斯《罗马史》第七十四至七十五卷（后期摘要本）","是役后所铸胜利钱背"],tags:["内战","会战","军赏"]},related:[]},
  {id:"world--202--p01",track:"world",year:202,yearApprox:true,dim:"politics",weight:2,title:"塞维鲁凯旋拱之立",summary:"东方之捷告成，都中立拱铸钱以纪其功。",detail:{background:"塞维鲁以两河之役为不世之功，欲借边功自固新立之统。",process:"约公元202至203年，罗马为立凯旋拱于卡皮托利之坡，钱背铸「帕提亚所获之大胜」之铭，其乡邑法尔斯亦刻王名。",impact:"拱之浮雕与钱铭为塞维鲁朝宣传之最要证；然帝之正统终倚军赏，元老院之命不过追认而已。",figures:["塞维鲁"],place:"罗马",state:"罗马帝国",sources:["罗马塞维鲁凯旋拱与浮雕","《奥古斯塔史·塞维鲁传》","塞维鲁朝钱币背文"],tags:["凯旋门","钱币","王朝"]},related:[]},
  {id:"world--208--m01",track:"world",year:208,yearApprox:false,dim:"military",weight:3,title:"塞维鲁北征喀里多尼亚",summary:"抱病临不列颠，深入北林而未能定诸部。",detail:{background:"不列颠边墙之外诸部破塞杀将，朝廷北顾；帝与其二子亲驻北方。",process:"公元208至211年，塞维鲁自埃勃拉库姆进兵，修墙堑与营道，据岛之北半而不能灭喀里多尼亚诸部，士卒疲于林泽。",impact:"帝死于军府而和议成，北境复守旧墙；不列颠自此为北方驻跸之地，其兵权重于西方诸省。",figures:["塞维鲁","卡拉卡拉"],place:"不列颠与北方（今英格兰北部、苏格兰）",state:"罗马帝国",sources:["希罗狄安《罗马帝国史》第七、八卷","狄奥·卡西乌斯《罗马史》第七十六卷（后期摘要本）","约克与边墙遗址考古报告"],tags:["不列颠","北征","边墙"]},related:[]},
  {id:"world--211--p01",track:"world",year:211,yearApprox:false,dim:"politics",weight:4,title:"埃勃拉库姆之崩",summary:"北方军府之死，二子并号而兄弟不相见。",detail:{background:"塞维鲁晚岁依北军以自重，遗命二子同受帝号，以金帛属之近卫。",process:"公元211年2月，塞维鲁卒于埃勃拉库姆（今约克）；卡拉卡拉与弟盖塔并立，而兄弟各置卫兵，不共一室。",impact:"父命之「共治」仅数月而弟见杀，自是帝室之亲不足恃，军之所欲辄为诏；朝廷与近卫之相市愈深。",figures:["塞维鲁","卡拉卡拉","盖塔"],place:"埃勃拉库姆（今英国约克）",state:"罗马帝国",sources:["狄奥·卡西乌斯《罗马史》第七十六至七十七卷（后期摘要本）","希罗狄安《罗马帝国史》第四卷","《奥古斯塔史·塞维鲁传》"],tags:["帝崩","并立","近卫军"]},related:[]},
  {id:"world--212--f01",track:"world",year:212,yearApprox:false,dim:"figure",weight:3,title:"盖塔之诛与除忆之令",summary:"弟毙于母怀，附从者同日就戮，名字尽削。",detail:{background:"盖塔为其母所护，军中两奉其名，其侍从、医人与旧臣皆成党羽。",process:"公元212年，卡拉卡拉于母前戕其弟，凡仆从医者同日见杀，都中株连者众；其像削于碑，名铲于币与军籍。",impact:"除忆之制自此见于家法之内，朝廷与罗马之民两相疑；未几乃以普授公民之敕广收天下之赋。",figures:["卡拉卡拉","盖塔","朱里亚·多姆娜"],place:"罗马",state:"罗马帝国",sources:["希罗狄安《罗马帝国史》第四卷","狄奥·卡西乌斯《罗马史》第七十七卷（后期摘要本）","铲削其名之碑铭与军籍"],tags:["宫闱","除忆","株连"]},related:[]},
  {id:"world--215--e01",track:"world",year:215,yearApprox:true,dim:"economy",weight:3,title:"银币减质与军费之增",summary:"钱枚骤多而含银日少，市直随之而腾。",detail:{background:"卡拉卡拉厚赏诸军以安其位，府库之金谷不足以给其费。",process:"约公元215年前后，银币之含银量自前朝之近半降至三成上下，钱枚之铸数倍增，又新立东方之税目以补其阙。",impact:"此为罗马币制三世纪崩坏之始阶；后世以减质为不言之赋，军饷与市肆之值相寻而涨。",figures:["卡拉卡拉"],place:"罗马与诸铸钱之所",state:"罗马帝国",sources:["三世纪初银币成色之测定与钱型序列","《奥古斯塔史·安敦尼·卡拉卡拉传》","埃及纸草所见物价与钱直"],tags:["币制","军饷","物价"]},related:[]},
  {id:"world--217--p01",track:"world",year:217,yearApprox:false,dim:"politics",weight:3,title:"骑士出身之君与东方之和",summary:"近卫长官骤登大位，以金帛易两河之兵。",detail:{background:"东征之军久怨其君，近卫军长官马克里努斯预于卡赖城下之谋。",process:"公元217年卡拉卡拉遇弑，马克里努斯被拥于东方军前；旋以巨金赂帕提亚王纳尔塞而还兵，且偿前朝之负。",impact:"元首出自骑士品为前所未有，元老之怨与诸军之轻慢并至；在位才逾年，塞维鲁之孙遂借东方军兴。",figures:["马克里努斯","纳尔塞"],place:"东方军前（今伊拉克北部）",state:"罗马帝国与帕提亚",sources:["希罗狄安《罗马帝国史》第四卷","狄奥·卡西乌斯《罗马史》第七十九卷（后期摘要本）","《奥古斯塔史·马克里努斯传》"],tags:["近卫军","和约","出身"]},related:[]},
  {id:"world--222--p01",track:"world",year:222,yearApprox:false,dim:"politics",weight:3,title:"亚历山大之立与母后之政",summary:"童子承统，外戚与法学士同预机要。",detail:{background:"东方军奉塞维鲁之孙以拒马克里努斯；其母为帕提亚贵族之女，长于宫廷。",process:"公元222年，十三岁之塞维鲁·亚历山大即帝位，母优力亚·玛玛主内廷，引用乌尔比安等法律之士当枢要，朝议稍循旧章。",impact:"外戚之政倚法士为纲，二十年之际法学著述最盛；然军之骄已深，十一年后母子俱死于营前。",figures:["塞维鲁·亚历山大","优力亚·玛玛","乌尔比安"],place:"罗马",state:"罗马帝国",sources:["《奥古斯塔史·亚历山大·塞维鲁传》","乌尔比安法学著作之《学说汇纂》辑文","是朝钱币与肖像雕刻"],tags:["母后","法士","外戚"]},related:[]},
  {id:"world--226--c01",track:"world",year:226,yearApprox:true,dim:"culture",weight:4,title:"阿尔达希尔之火坛钱式",summary:"新王定币式，以火坛与王号并铸一背。",detail:{background:"阿尔达希尔既破帕提亚之末王，封建制循其旧而名号一新。",process:"约公元224至226年，定钱式：正面王像与高冠，背为火坛与二侍者，铭称玛兹达所立之王；又置国家之火以为王权之凭。",impact:"自是萨珊之王号、火坛与币式三位一体，其制西抵罗马之界、东被印度之边，历四百年不易。",figures:["阿尔达希尔","沙普尔一世"],place:"法尔斯（今伊朗法尔斯省）",state:"萨珊波斯",sources:["阿尔达希尔与沙普尔朝钱币","沙普尔一世纳克什－鲁斯塔姆铭刻","近代所传萨珊王谱与碑志校勘"],tags:["萨珊","火坛","钱币"]},related:[]},
  {id:"world--230--x01",track:"world",year:230,yearApprox:true,dim:"explore",weight:3,title:"摩尼遣徒东行",summary:"以书与画为命，使者四出至印度之滨。",detail:{background:"摩尼出于巴比伦尼亚之洗礼团体，及壮自立其宗，自谓受使命为「承继之使」。",process:"约公元230至240年间，摩尼遣徒分道东行，入印度河流域与丝路诸邑，以书札与画轴陈其教之纲目；其文以数语传抄。",impact:"此为古代宗教以文书图像并行布教之罕见例，东方一支由是入中亚；残叶之出土地，至今为交通史之要证。",figures:["摩尼"],place:"巴比伦尼亚与东行诸道",state:"萨珊波斯与诸传教之道",sources:["科隆摩尼抄本所记行教之序","摩尼《书信集》与《基础书》之校勘本","《沙卜拉干》巴列维文残篇"],tags:["传教","写本","东行"]},related:[]},
  {id:"world--235--m01",track:"world",year:235,yearApprox:false,dim:"military",weight:5,title:"莱茵军之变与元首之殒",summary:"军府自择其君，元老院始失其选择之权。",detail:{background:"亚历山大母子死于营前，莱茵诸军以主帅之名相拥；旧朝之亲党并诛。",process:"公元235年，莱茵营奉马克西米努斯为君，帝起于色雷斯之伍，元老院迫而承之，其子亦号奥古斯都。",impact:"自是五十年间为帝者数十，多出军门，内战与外患相乘；史家以是岁为三世纪危机之始。",figures:["马克西米努斯","塞维鲁·亚历山大"],place:"莱茵前营（今德国美因茨一带）",state:"罗马帝国",sources:["《奥古斯塔史·马克西米努斯传》","希罗狄安《罗马帝国史》第七卷","是朝钱币与军砖铭"],tags:["军人皇帝","危机","莱茵"]},related:[]},
  {id:"world--241--c01",track:"world",year:241,yearApprox:true,dim:"culture",weight:3,title:"摩尼以《沙卜拉干》见王庭",summary:"上书陈宇宙之阶，并携画轴以尽其义。",detail:{background:"萨珊二主更替之际，东方诸教各求王庭之援以立其宗。",process:"约公元240至241年，摩尼以巴列维文撰《沙卜拉干》献沙普尔一世，陈创物、灾变与回归之阶，并以画轴图其义以示众。",impact:"其宗由是获萨珊之护而东行渐广；后以祭司之请见逐，流亡于叙利亚与中亚之间，其画本之传统遂开。",figures:["摩尼","沙普尔一世"],place:"萨珊王廷（今伊朗南部）",state:"萨珊波斯",sources:["《沙卜拉干》巴列维文残篇与校勘本","比鲁尼《诸国编年史》所记摩尼与纪元","科隆摩尼抄本残叶"],tags:["摩尼教","王庭","画本"]},related:[]},
  {id:"world--244--m01",track:"world",year:244,yearApprox:true,dim:"military",weight:3,title:"米切之役与帝殁军前",summary:"两河相接一役，罗马之纪与波斯之铭各说其胜。",detail:{background:"戈尔狄安三世以近臣当国，议复东方之界，举兵度底格里斯。",process:"约公元244年2月，两军遇于米切（今伊拉克北部），未几帝殁于军前；阿拉伯之腓力代立，且以重赂与波斯结约而还。",impact:"沙普尔之铭刻自纪其功，罗马诸史则讳其败，两证并立而其事难明；东方之患自此暂弭，而边兵之骄益甚。",figures:["戈尔狄安三世","沙普尔一世","腓力"],place:"美索不达米亚米切（今巴格达北）",state:"罗马帝国与萨珊波斯",sources:["沙普尔一世纳克什－鲁斯塔姆铭刻","《奥古斯塔史·三戈尔狄安传》","是朝钱币与近东诸史之纪年"],tags:["两河","阵殁","和赂"]},related:[]},
  {id:"world--248--p01",track:"world",year:248,yearApprox:false,dim:"politics",weight:2,title:"罗马建城千年之庆",summary:"逢千载之会，集百戏而国帑已匮。",detail:{background:"建城之纪自旧算而来，至是适千年，朝野以为不世之祥。",process:"公元248年4月，腓力行建城千年之庆，集角士与异兽于诸场，铸钱纪其元；是岁冬，边军复有两将称号之事。",impact:"庆典之费与赂边之金并竭府库，未几莱茵与多瑙之军屡叛；千年之说过为虚文，而三世纪之局已成。",figures:["腓力"],place:"罗马",state:"罗马帝国",sources:["罗马建城千年之钱背与币铭","奥勒利乌斯·维克多《诸帝志》第二十八节","优特罗皮乌斯《罗马志纲要》第九卷"],tags:["庆典","钱币","边患"]},related:[]},
  {id:"world--251--m01",track:"world",year:251,yearApprox:false,dim:"military",weight:4,title:"阿布里图斯之败与帝殁于阵",summary:"皇帝为罗马史上首见殁于对外之阵者。",detail:{background:"哥特人渡黑海入色雷斯，朝廷以二帝并出御之，德西乌斯挟其子同行。",process:"公元251年，两军遇于阿布里图斯（今保加利亚巴尔加腊一带），帝陷泽中而死，其子并殁；加卢斯继之，且以岁赂与哥人约而还。",impact:"国威之大辱与岁赂之例并启于此时；多瑙防务自此愈赖部族之兵，哥特之众渐成东方之患。",figures:["德西乌斯","加卢斯"],place:"色雷斯阿布里图斯（今保加利亚东北）",state:"罗马帝国与哥特诸部",sources:["狄奥·卡西乌斯《罗马史》第八十卷（后期摘要本）","奥勒利乌斯·维克多《诸帝志》","色雷斯与黑海沿岸之窖藏钱币"],tags:["哥特","阵殁","岁赂"]},related:[]},
  {id:"world--251--c01",track:"world",year:251,yearApprox:true,dim:"culture",weight:4,title:"德西乌斯普祭之敕",summary:"令普行奠祭以验其忠，祭状纸草由是而生。",detail:{background:"朝廷以国祭为齐民之准，欲振前朝之弛；诸会之众独不肯拜。",process:"约公元250至251年，颁敕令普行奠祭，有司给「已祭之状」为凭；亚历山大与迦太基诸会多被系问，背教与坚守者相望于路。",impact:"此为帝国首次以统一之敕行逼迫，教内关于背教者与复入者之争延数十年；殉道之名册开圣人传记之先。",figures:["德西乌斯","居普良"],place:"帝国东部诸省与迦太基",state:"罗马帝国与诸教会",sources:["埃及出土「祭礼之状」纸草","居普良《论背教者》与书信","优西比乌《教会史》第七卷"],tags:["逼迫","教会","纸草"]},related:[]},
  {id:"world--257--i01",track:"world",year:257,yearApprox:false,dim:"institution",weight:3,title:"瓦勒良敕与圣职之禁",summary:"禁其聚会、没其会产，迫害始有法条可据。",detail:{background:"边患日亟，有司以诸会之不祭神为乱军心、亏国祀之渐。",process:"公元257年夏颁第一敕：禁诸会之聚，夺其产业而令其首领归本；翌年第二敕直诛主教与执事，没其田宅。",impact:"逼迫以法律之形出之，故主教之坐与籍没皆有案可凭；迦太基与罗马所记狱辞，为教会与帝国关系之最直证据。",figures:["瓦勒良","西克斯图斯","劳伦修斯"],place:"罗马与迦太基",state:"罗马帝国",sources:["《迦太基主教起居注》与会议行状","居普良书信与《论殉道者之福》","瓦勒良两敕之传本与近世校勘"],tags:["法条","逼迫","教会财产"]},related:[]},
  {id:"world--262--p01",track:"world",year:262,yearApprox:true,dim:"politics",weight:4,title:"元老不得领军之令",summary:"贵族之武职遂绝，边镇一归于军人。",detail:{background:"三十年间军兴不绝，诸以贵游之身领边兵而僭号者相踵。",process:"约公元262年后，加里恩努斯令元老之族不得为军团将与行省督，其任悉归骑士品与军中之吏。",impact:"此举非一时之制，而开职业军人与文官分途之局；元老之贵与兵柄遂离，四世纪之官制胚胎于此。",figures:["加里恩努斯"],place:"意大利与诸边省",state:"罗马帝国",sources:["佐西默斯《新史》第一卷","《奥古斯塔史·加里恩努斯传》","军团将与行省督之署名碑铭"],tags:["军制","元老院","官阶"]},related:[]},
  {id:"world--267--m01",track:"world",year:267,yearApprox:true,dim:"military",weight:4,title:"机动骑兵之设",summary:"精骑别为军府，闻警而赴，不守一塞。",detail:{background:"哥特与萨尔玛提亚之骑屡破边塞，塞上诸营声气不相及。",process:"约公元264至268年间，加里恩努斯别立骑兵之旅，屯于米兰一带，置都统一人之任，使骑与步异其编制。",impact:"罗马军由塞守转向野战之基在此；戴克里先之边军与内军分区，四世纪之野战军团，皆循此轨。",figures:["加里恩努斯","奥勒良"],place:"波河诸道与米兰",state:"罗马帝国",sources:["佐西默斯《新史》第一卷","《奥古斯塔史·加里恩努斯传》","意大利北境军镇之铭文与遗址"],tags:["骑兵","野战军","军制"]},related:[]},
  {id:"world--270--p01",track:"world",year:270,yearApprox:true,dim:"politics",weight:4,title:"帕尔米拉之兴与东方之寄",summary:"商队之都渐为王业，幼主与太后临东方诸省。",detail:{background:"瓦勒良殁于波斯，东方无以守；帕尔米拉之家长世掌商税与部族之兵。",process:"约公元267至270年，奥登纳图斯承其父之任而号王者，妻泽诺比娅以幼子之名摄东方，自署钱币与省官。",impact:"诸省离而复合、复合而离，帕尔米拉一变商邑为王都，为三世纪分裂之最著者；其亡也，东方之贵族随之而衰。",figures:["奥登纳图斯","泽诺比娅"],place:"帕尔米拉与东方诸省",state:"帕尔米拉与罗马帝国",sources:["帕尔米拉双语铭刻与称王时期钱币","佐西默斯《新史》第一卷","《奥古斯塔史·三十僭主传》"],tags:["帕尔米拉","分裂","太后"]},related:[]},
  {id:"world--274--p01",track:"world",year:274,yearApprox:false,dim:"politics",weight:5,title:"奥勒良复合一国之土",summary:"东收帕尔米拉，西复高卢之伪朝，号曰恢复者。",detail:{background:"帝国裂为三：西方有高卢之伪帝，东方有帕尔米拉，边镇屡易其主。",process:"公元272至274年，奥勒良先东举破泽诺比娅而取帕尔米拉，后西击图里库斯于沙隆一带，尽复旧境；凯旋之日陈二后与伪帝之像于前。",impact:"其号「世界之恢复者」铸于钱背，见一时之功；虽旋有帕尔米拉之复叛与帝之遇弑，国土之复合犹延两百年。",figures:["奥勒良","泽诺比娅","图里库斯"],place:"帕尔米拉与高卢",state:"罗马帝国",sources:["佐西默斯《新史》第一卷","奥勒良朝钱币与恢复者之铭","《奥古斯塔史·奥勒良传》"],tags:["复国","凯旋","分裂"]},related:[]},
  {id:"world--275--m01",track:"world",year:275,yearApprox:false,dim:"military",weight:3,title:"奥勒良遇弑于军府",summary:"近侍伪为密函，诸将以自危之手刃其君。",detail:{background:"帝课役严急，营缮之吏惧于追责；军中旧怨未解。",process:"公元275年秋，书写之侍伪作密函，召诸将自言且见诛，遂共弑帝于色雷斯之军府；军中既知其诬，元老院乃奉塔西佗。",impact:"一吏之伪书能杀方镇之主，见军府自危之深；自是兵将相猜，复国之势遂不竞于北方。",figures:["奥勒良","塔西佗"],place:"色雷斯军府（今土耳其西北）",state:"罗马帝国",sources:["佐西默斯《新史》第一卷","奥勒利乌斯·维克多《诸帝志》","《奥古斯塔史·奥勒良传》"],tags:["弑君","军府","告讦"]},related:[]},
  {id:"world--282--p01",track:"world",year:282,yearApprox:false,dim:"politics",weight:3,title:"卡鲁斯东征与雷殛之说",summary:"自步兵而登大位，旋殁于两河之军前。",detail:{background:"禁卫长官以老成为众所推，其年已高，二子随立为嗣。",process:"公元282至283年，卡鲁斯率军度底格里斯，取泰西封；未几暴卒，史家或归之雷震，军中旋奉其二子并承其号。",impact:"雷殛之说出于史家之笔而非定案；东方之役虽捷而不能久守，戴克里先起于其行伍之中，代其嗣而立。",figures:["卡鲁斯","卡里努斯","戴克里先"],place:"美索不达米亚",state:"罗马帝国与萨珊波斯",sources:["《奥古斯塔史·卡鲁斯二子传》","优特罗皮乌斯《罗马志纲要》第九卷","奥勒利乌斯·维克多《诸帝志》"],tags:["东征","暴卒","嗣位"]},related:[]},
  {id:"world--284--p01",track:"world",year:284,yearApprox:false,dim:"politics",weight:5,title:"戴克里先之立与主上之号",summary:"军府之选不复讳其源，君臣之义改为主奴之礼。",detail:{background:"卡里努斯死于多瑙之师，军中之众以达尔马提亚之将为请，时年四十。",process:"公元284年11月，戴克里先受紫衣于尼科米底亚；数年之内不复称元首之旧号，而于文书与朝仪中称「主上」。",impact:"元首之制至是而尽变，东方之朝仪与跪拜之礼入于公庭；四帝之局、省制之改与大迫害，皆基此新体。",figures:["戴克里先","卡里努斯"],place:"尼科米底亚（今土耳其伊兹密特）",state:"罗马帝国",sources:["优特罗皮乌斯《罗马志纲要》第九卷","奥勒利乌斯·维克多《诸帝志》第三十九节","是朝文书用语之铭刻与钱币"],tags:["主上之号","朝仪","军府"]},related:[]},
  {id:"world--286--i01",track:"world",year:286,yearApprox:false,dim:"institution",weight:4,title:"同治之局与两廷之分",summary:"以旧将主西方军政，号令自此双行。",detail:{background:"边境之警并至，一人之所能不给；其同军之旧友马克西米安起于行伍。",process:"公元285至286年，戴克里先以马克西米安为同治之将，寻号奥古斯都，西方兵政归之；二廷各置官府、钱监与亲军。",impact:"此为四帝共治之初步，分任而非分国；双行之令既济一时之急，亦启后此东西两廷长期分立之渐。",figures:["戴克里先","马克西米安"],place:"尼科米底亚与米兰",state:"罗马帝国",sources:["双署之钱币与诸都邑之官署铭","《晚期拉丁颂辞集》所收三世纪末之作","优特罗皮乌斯《罗马志纲要》第九卷"],tags:["共治","两廷","钱监"]},related:[]},
  {id:"world--297--m01",track:"world",year:297,yearApprox:false,dim:"military",weight:4,title:"伽列里乌斯之东胜",summary:"度山乘虚，获波斯王之后宫与宝辇。",detail:{background:"前岁卡莱一带之败，罗马军失其锐，东方之任更责成于恺撒之府。",process:"公元297年，伽列里乌斯度阿底亚贝尼之山道，掩击其辎重，获王之后宫、姊妹与宝辇；遂定亚美尼亚之界，割五区于底格里斯以东。",impact:"此约为四十年间东界之定局，罗马由是有亚美尼亚之王位与通道；两河商路之北道亦随之以宁。",figures:["伽列里乌斯","纳尔塞","提里达特斯"],place:"亚美尼亚与阿底亚贝尼",state:"罗马帝国与萨珊波斯",sources:["《晚期拉丁颂辞集》论是役之辞","是朝钱背与东方诸省之铸币","优特罗皮乌斯《罗马志纲要》第九卷戴克里先朝事"],tags:["东界","亚美尼亚","和议"]},related:[]},
  {id:"world--298--i01",track:"world",year:298,yearApprox:true,dim:"institution",weight:4,title:"行省细分与军民分治",summary:"省额倍增，领军者不复与民讼钱谷。",detail:{background:"旧省之大者难以弹压，二百年之乱多以一省之资奉一人之僭。",process:"约公元297至298年，行省自五十许分为近百，又合为十余管区、四大区，各置督府；军团之将不与民讼，钱谷别为曹署。",impact:"此制抑藩镇而繁吏治，赋册与驿传因之加密；四世纪之廷与后世拜占庭之省制，皆其枝裔。",figures:["戴克里先"],place:"帝国诸省",state:"罗马帝国",sources:["《维尔罗纳名册》所载行省与职官","拉克坦提乌斯《论迫害者之死》","边镇与督府之署名铭文"],tags:["省制","分权","职官"]},related:[]},
  {id:"world--300--i01",track:"world",year:300,yearApprox:true,dim:"institution",weight:3,title:"两朝敕典之私辑",summary:"法士各辑历代之敕，国法之编自此有本。",detail:{background:"累朝敕格岁出而无编，有司与讼家苦其错出矛盾。",process:"约公元291至300年间，近卫军长官格列高里乌斯辑历朝敕为十五卷，霍尔密齐亚努斯续辑至三世纪之末，皆以私纂而行之有司。",impact:"此二编为六世纪国法之骨干，断片今存；法学之业自是移于宫廷，罗马法之传始有可据之定本。",figures:["格列高里乌斯","霍尔密齐亚努斯"],place:"罗马与东方之廷",state:"罗马帝国",sources:["《格列高里乌斯法典》断片","《霍尔密齐亚努斯法典》断片","优士丁尼《法典》之序令"],tags:["法典","敕令","法学"]},related:[]},
  {id:"world--303--c01",track:"world",year:303,yearApprox:false,dim:"culture",weight:4,title:"最后大迫害之诏",summary:"连下三诏：焚经、毁堂、禁止聚会。",detail:{background:"尼科米底亚之宫遭火，有司以是罪诸会之众，朝议遂主峻法。",process:"公元303年2月起连下三诏：焚其经书、毁其会堂、禁其聚会，又令普行奠祭；东方诸省行之尤峻，至306年后稍弛。",impact:"十年之逼迫未能绝其教，反启教内关于复入者与会产之争；311年之宽容诏与313年之还产令，皆循此局而来。",figures:["戴克里先","伽列里乌斯"],place:"尼科米底亚与东方诸省",state:"罗马帝国",sources:["拉克坦提乌斯《论迫害者之死》","优西比乌《教会史》第八卷","是时东方诸省之纸草与刑案残文"],tags:["逼迫","诏令","教会"]},related:[]},
  {id:"world--305--p01",track:"world",year:305,yearApprox:false,dim:"politics",weight:4,title:"两主同日逊位",summary:"在位二十年者退处私宫，继承之局付与军心。",detail:{background:"帝以疾倦于政，且欲成其分任世袭之制；同治之主亦以年高请老。",process:"公元305年5月1日，戴克里先与马克西米安同日逊位，二恺撒升为奥古斯都，另立二恺撒于军前；帝归乡里，营离宫于海滨。",impact:"主动逊位之举在古代为创见，然不及两年而继承之局尽坏；四帝之制转为内战，帝国再入多主之争。",figures:["戴克里先","马克西米安","君士坦提乌斯"],place:"尼科米底亚与斯帕拉托（今克罗地亚斯普利特）",state:"罗马帝国",sources:["拉克坦提乌斯《论迫害者之死》","斯帕拉托戴克里先离宫遗址考古报告","优特罗皮乌斯《罗马志纲要》第九卷"],tags:["逊位","共治","离宫"]},related:[]},
  {id:"world--306--p01",track:"world",year:306,yearApprox:false,dim:"politics",weight:4,title:"约克军中之拥立",summary:"父死边府，将士不待朝命而奉其子。",detail:{background:"君士坦提乌斯以西方之主驻节不列颠，方课边塞之役，其子随军。",process:"公元306年7月25日，君士坦提乌斯卒于埃勃拉库姆，部下即拥其子君士坦丁为奥古斯都；东方之廷不许其号，只准以恺撒之名。",impact:"帝号之与夺自此取决于军心而非成命；十年之内此人以两场内战并有其地，四世纪之局由是而定。",figures:["君士坦丁","君士坦提乌斯"],place:"埃勃拉库姆（今英国约克）",state:"罗马帝国",sources:["拉克坦提乌斯《论迫害者之死》","优西比乌《君士坦丁传》","是朝西方诸铸监之钱背"],tags:["拥立","不列颠","帝号"]},related:[]},
  {id:"world--311--i01",track:"world",year:311,yearApprox:false,dim:"institution",weight:4,title:"逼迫之止与宽容之诏",summary:"病中的恺撒许其复会，命有司勿复扰。",detail:{background:"逼迫历八年而信众不减，东方之兵又屡困于内战与边患。",process:"公元311年4月末，伽列里乌斯于萨尔尼卡病中颁诏，许基督之徒复其聚会、不受妨碍，但令其为君主与国之安堵祈愿。",impact:"此为逼迫政策之正式收场，亦为313年两帝联名文书之张本；教会之法律地位自此转圜，其产权与豁免渐有可凭。",figures:["伽列里乌斯"],place:"萨尔尼卡（今塞尔维亚斯雷姆斯基卡尔洛夫奇一带）",state:"罗马帝国",sources:["拉克坦提乌斯《论迫害者之死》所载诏文","优西比乌《教会史》第八卷所录诏书","该地离宫与铸监遗址报告"],tags:["宽容","诏书","教会财产"]},related:[]},
  {id:"world--312--m01",track:"world",year:312,yearApprox:false,dim:"military",weight:5,title:"米尔维安桥之役",summary:"台伯河上一日，西方之敌覆于桥下。",detail:{background:"马克森提乌斯据罗马、意大利与非洲，以近卫军与哥特附众守北道。",process:"公元312年10月28日，君士坦丁自北而下，会战于都城北门外；其骑先破敌骑，步兵退而相挤于桥上，桥坏，多坠于河，翌日入城。",impact:"此役使西方尽归一主，亦留下异象之两说：一谓日中见兆，一谓圣使见于梦；后世之礼典与艺事皆缘此传。",figures:["君士坦丁","马克森提乌斯"],place:"罗马城北台伯河之米尔维安桥",state:"罗马帝国",sources:["《晚期拉丁颂辞集》三二一年之颂","拉克坦提乌斯《论迫害者之死》","优西比乌《君士坦丁传》","该战场出土兵器与骸骨之考古报告"],tags:["内战","会战","异象"]},related:[]},
  {id:"world--313--c01",track:"world",year:313,yearApprox:false,dim:"culture",weight:5,title:"米兰之会与教产之还",summary:"两帝会议于米兰，命还诸会之堂与坟地。",detail:{background:"君士坦丁与李锡尼联姻于米兰；东方之逼迫初弛，而会产多已在官。",process:"公元313年2月，两帝会于米兰定议：听信者自由崇拜，并以文书命东方有司归还会堂与坟地，其中已有买主者偿其直。",impact:"此不以一纸定国教，而以法令收逼迫之残；后世所谓「米兰敕令」即指此文与同年夏李锡尼之复文，教会之产权自此有凭。",figures:["君士坦丁","李锡尼"],place:"米兰与东方诸省",state:"罗马帝国",sources:["拉克坦提乌斯《论迫害者之死》所载之文","优西比乌《教会史》第十卷所录希腊文本","是朝钱币与诸省界内之碑铭"],tags:["宽容","教会产业","两帝"]},related:[]},
  {id:"world--317--i01",track:"world",year:317,yearApprox:true,dim:"institution",weight:3,title:"边地离宫与铸监之移",summary:"帝于乡里大修宫邑，钱谷之司渐就近边。",detail:{background:"旧都之官府与财谷远在意国，多瑙防区屡经战乱而需临视。",process:"约公元313至317年间，君士坦丁于其乡里纳伊苏斯之旁大筑宫邑，名其庄曰梅达纳，置监铸钱，分徙牧守于近边。",impact:"此为四世纪诸帝就近边建宫城之始例，帝国之枢机自此渐离罗马；其邑之废兴，为巴尔干考古之所重。",figures:["君士坦丁"],place:"纳伊苏斯与梅达纳（今塞尔维亚尼什旁）",state:"罗马帝国",sources:["梅达纳离宫遗址发掘报告","是朝钱币与行省职官名册","奥勒利乌斯·维克多《诸帝志》论其乡里"],tags:["宫邑","铸监","行省"]},related:[]},
  {id:"world--321--i01",track:"world",year:321,yearApprox:false,dim:"institution",weight:4,title:"星期日休止之令",summary:"以法律定一周之休，田间之作则不禁。",detail:{background:"旧历以集市之日为节，诸会则以首日聚咏，二者适在同一日；讼狱之繁亦须分理。",process:"公元321年3月7日，君士坦丁令诸城之法官、居民与百工以「尊贵之日」休止，惟田畴之工作不在此限；此令后辑入国法。",impact:"此为帝国以法律定一周休务之始；未几又许民愿听主教之断者从其断，教会裁判与世俗官府相参之例由是而开。",figures:["君士坦丁"],place:"罗马与诸省",state:"罗马帝国",sources:["优士丁尼《法典》所辑休止之令","优西比乌《君士坦丁传》第四卷","《狄奥多西法典》所辑主教听讼之条"],tags:["历日","法律","教会裁判"]},related:[]},
  {id:"world--323--p01",track:"world",year:323,yearApprox:true,dim:"politics",weight:4,title:"东西两主之战与共治之终",summary:"两役一疫之间，东方之君失国而一统遂成。",detail:{background:"两主共治之约已再破：拜占庭之界与边畔之衅相继而起。",process:"约公元323至324年，君士坦丁两破李锡尼于阿德里亚堡与克里索波利斯，前役值大风起（古典诸史两说其占），后役追至拜占庭；明年其众降，寻死于帖撒罗尼迦。",impact:"自戴克里先逊位以来垂三十年的共治，至是归于一人；新都之筑、尼西亚之会与币制之改，皆出此局。是岁之先后，编年诸家至今异同。",figures:["君士坦丁","李锡尼"],place:"色雷斯与比提尼亚（今土耳其西北）",state:"罗马帝国",sources:["优西比乌《君士坦丁传》第二卷","佐西默斯《新史》第一卷","是役后所铸「胜者」钱背"],tags:["内战","一统","编年之争"]},related:[]},
  {id:"world--325--p01",track:"world",year:325,yearApprox:false,dim:"politics",weight:5,title:"尼西亚之大会议",summary:"三百余主教会于边城，帝预末座而断其议。",detail:{background:"亚历山太长老阿利乌之说遍于东方诸会，书信往复，裂其众；朝使按行不能解。",process:"公元325年5至8月间，诸省主教三百余人会于尼西亚，君士坦丁亲临，坐于末席；先议逾越节同守之例，后以「与父同性同体」一句定其信辞，拒签者二人随阿利乌同徙。",impact:"此为帝国首次召集之全国主教会，信理与法规皆借帝命为势；「尼西亚」之名自此为诸家信经之标，亦启后此六十余年之争。",figures:["君士坦丁","霍修斯","优特比乌斯","阿利乌"],place:"尼西亚（今土耳其伊兹尼克）",state:"罗马帝国与诸教会",sources:["会议信经与会中之书（见于后世教会史所引）","优西比乌《君士坦丁传》第三卷","索克拉底《教会史》第一卷","会议签名主教之名录"],tags:["公会议","信经","阿利乌之争"]},related:[]},
  {id:"world--326--a01",track:"world",year:326,yearApprox:true,dim:"art",weight:4,title:"圣墓与橄榄山诸堂之筑",summary:"凿岩陵而辟圣苑，长厅与圆亭并起于东方。",detail:{background:"帝遣使与母后至东方访求遗迹，欲以宏宇表其敬而镇其地。",process:"约公元326至335年，于耶路撒冷凿陵辟苑，旁建大殿与圆亭；又于伯利恒与橄榄山各起一堂，料石取自都邑与诸省。",impact:"罗马之殿制自是改为长厅与穹亭相配之式，为后世千年教堂之规模；圣迹之访求与营建，亦成东方政策之一端。",figures:["君士坦丁","海伦娜"],place:"耶路撒冷与伯利恒",state:"罗马帝国",sources:["优西比乌《君士坦丁传》第三卷","圣墓教堂历代层位与考古报告","公元333年行旅者所记诸堂"],tags:["教堂","建筑","圣迹"]},related:[]},
  {id:"world--332--i01",track:"world",year:332,yearApprox:true,dim:"institution",weight:3,title:"塞外之教众与边外之约",summary:"边外之民族以牧人与书市易刀兵之约。",detail:{background:"多瑙河北之哥特有久在罗马为佣者，还乡为其同类牧养；边民之众渐附于农市。",process:"约公元332年前后，乌尔菲拉随其族之牧者与罗马之众相结，寻受按察之任；其民塞外渐立会众，贸易与人质之相约亦定。",impact:"此为古代边外民族以文字与信仰内属之先例；其族后分东西而内迁，未及六十年，塞外之教遂成塞内之争。",figures:["乌尔菲拉","君士坦丁"],place:"多瑙河北岸（今罗马尼亚瓦拉几亚一带）",state:"罗马帝国与哥特诸部",sources:["索克拉底《教会史》第四卷","亚纳修斯书信论塞外之教众","边外窖藏与哥特遗物之考古刊布"],tags:["边外","传教","盟约"]},related:[]},
  {id:"world--337--p01",track:"world",year:337,yearApprox:false,dim:"politics",weight:4,title:"君士坦丁之崩与三子并号",summary:"一统之主殁于东方之宫，三子分土而军定其诛。",detail:{background:"帝老于尼科米底亚之宫，诸子各拥兵于边，近臣与军府互有所主。",process:"公元337年5月22日帝殁；数月之内三子并受奥古斯都之号，君士坦丁堡军前公审其伯叔之党，王族数人死于众。",impact:"父死而三子分其土，帝国东西之守令自此各异；其诸朝之教争、边战与宫变，皆循此分立之局而深。",figures:["君士坦丁","君士坦提乌斯","康斯坦斯"],place:"尼科米底亚与君士坦丁堡",state:"罗马帝国",sources:["优西比乌《君士坦丁传》第四卷","奥勒利乌斯·维克多《诸帝志》","佐西默斯《新史》第二卷"],tags:["帝崩","分治","军诛"]},related:[]},
  {id:"world--350--p01",track:"world",year:350,yearApprox:false,dim:"politics",weight:4,title:"马格嫩提乌斯之弑主僭号",summary:"西方之主死于宴所，节钺与玺并为军有。",detail:{background:"康斯坦斯倚近臣而诛名将，西部之军怨；宴饮之间事变忽起。",process:"公元350年1月，近卫军长官马格嫩提乌斯于高卢之宴所弑康斯坦斯，旋据西方诸省，杀其诸子；东方之廷初讳之，寻与交兵。",impact:"西方数省入于僭主之手，莱茵与多瑙之边兵尽调于内战；三年后东方之军始入其都，而罗马之西势由此大耗。",figures:["康斯坦斯","马格嫩提乌斯"],place:"高卢南部（今法国埃布罗杜努姆一带）",state:"罗马帝国",sources:["尤特罗皮乌斯《罗马志纲要》第十卷","奥勒利乌斯·维克多《诸帝志》第四十二节","阿米安努斯《罗马史》追叙其乱之诸章"],tags:["弑主","僭位","内战"]},related:[]},
  {id:"world--355--c01",track:"world",year:355,yearApprox:true,dim:"culture",weight:3,title:"牺牲之禁与神庙之闭",summary:"重申勿祀之令，庙门既闭而乡里犹自若。",detail:{background:"东方之廷屡申勿祀之条，奉行宽猛不一；乡村之旧礼仍相承不绝。",process:"约公元355至356年，君士坦提乌斯重申禁牺牲、闭神庙之令，并案家中偶像与私祭之犯；有司至以斧火治其材。",impact:"此令于诸省之效不一，乡里之抗命自此为常；未几尤利安立宽容之政而暂弛，两教之界遂渐判然。",figures:["君士坦提乌斯"],place:"帝国诸省",state:"罗马帝国",sources:["《狄奥多西法典》所辑禁祀之令","阿米安努斯《罗马史》第十六、二十一卷","四世纪教父论庙宇改寺之文"],tags:["祭祀","法令","乡里"]},related:[]},
  {id:"world--356--x01",track:"world",year:356,yearApprox:true,dim:"explore",weight:2,title:"罗马三使之至阿拉巴伊切",summary:"以生于印度者为使，三度南行抵红海之南。",detail:{background:"君士坦提乌斯结阿拉巴伊切诸王以通海路，又欲固其地商人之约。",process:"约公元354至358年间，生于印度之提奥菲洛三度衔命南行，至希木叶尔之廷与印度西岸诸邑，于其地立碑纪罗马之使。",impact:"此见于后世教会史之摘篇，为四世纪罗马通阿拉伯海与红海南岸之最直记事；其碑至五世纪犹存其处。",figures:["提奥菲洛","君士坦提乌斯"],place:"阿拉巴伊切与印度西岸（今也门与印度西海岸）",state:"罗马帝国与南方诸国",sources:["斐洛斯特吉乌斯《教会史》（后世《书录》所存摘篇）","阿米安努斯《罗马史》第二十三卷论其地","南阿拉伯铭刻与航路之近世校勘"],tags:["红海","使节","碑刻"]},related:[]},
  {id:"world--357--f01",track:"world",year:357,yearApprox:false,dim:"figure",weight:3,title:"尤利安以少众守莱茵",summary:"亲王以弱旅当阿雷曼尼之众，军名由是而起。",detail:{background:"西方之边自内战以后久虚，阿雷曼尼诸王度莱茵，法兰克据其北岸。",process:"公元357年，尤利安驻于阿尔根托拉图姆，以不满万人当诸部连衡之众（据阿米安努斯所记，两军之数诸史互异），身先士卒而胜之，军士奉为君。",impact:"此役定上游莱茵十余年之安，亦成其兵名；四年后东方之军奉之，与都廷之裂遂不可合。",figures:["尤利安","阿米安努斯","克罗多马里乌斯"],place:"阿尔根托拉图姆（今法国斯特拉斯堡）",state:"罗马帝国",sources:["阿米安努斯《罗马史》第十六卷","尤利安书信与诏令之辑本","斯特拉斯堡罗马军营与城墙遗址报告"],tags:["莱茵","亲王","兵名"]},related:[]},
  {id:"world--363--m01",track:"world",year:363,yearApprox:false,dim:"military",weight:4,title:"萨珊阵前之殁与割地之和",summary:"皇帝死于东征之军前，退师乃割两河之界。",detail:{background:"尤利安以大兵度底格里斯，欲复美索不达米亚；波斯行坚壁之策，粮道日匮。",process:"公元363年6月26日，帝于军前中矛而殁，自言为无名之卒所刺；军乃奉约维安，苦战而出，以割五郡、弃尼西比斯之市易结和而还。",impact:"自是罗马在东方失两河之屏障与亚美尼亚之凭，尼西比斯之学校徙于埃德萨；东方之界至五世纪不复西移。",figures:["尤利安","约维安","沙普尔二世"],place:"萨珊境（今伊拉克北部）",state:"罗马帝国与萨珊波斯",sources:["阿米安努斯《罗马史》第二十四至二十五卷","优特罗皮乌斯《罗马志纲要》第十卷","是朝东方界内之碑与钱币"],tags:["东征","阵殁","割地"]},related:[]},
  {id:"world--365--d01",track:"world",year:365,yearApprox:false,dim:"disaster",weight:4,title:"克里特之震与海啸之犯港",summary:"地大震而海退复至，舟有人城者、浮于宫上者。",detail:{background:"帝国东部之都邑多仰海运，港内舟船山积；亚历山大城正当克里特之北。",process:"公元365年7月21日，海震起于克里特，海水先退而后涌，坏港邑，舟有入城者、有浮于宫室之上者；据史家所记溺者以万数，古典之数多夸。",impact:"君士坦丁堡自是岁常以此日追念，埃及之粮运与港道为之改理；此事并见诸史文、历书与讲道之篇。",figures:["瓦伦斯","优提基乌斯"],place:"亚历山大城与克里特海",state:"罗马帝国",sources:["阿米安努斯《罗马史》第二十六卷","索佐门诺斯《教会史》","亚历山大城与克里特之层位与纪年铭刻"],tags:["地震","海啸","粮运"]},related:[]},
  {id:"world--372--c01",track:"world",year:372,yearApprox:true,dim:"culture",weight:4,title:"该撒利亚之病舍邑与修规",summary:"以大姓之财立常养之邑，以条规束众修之行。",detail:{background:"该撒利亚主教巴西尔以隐修为务，又忧饥馑疾疫之无养者。",process:"约公元370至372年，巴西尔于该撒利亚城外治邑立病舍、旅舍与匠作之居，后世称其地为「巴西尔之城」；又为众修者定律条，东西通行。",impact:"此为古代以教会之资立常设病舍之最著例；其规条至今为东方修道之蓝本，都邑之慈善自此渐有定制。",figures:["巴西尔","额我略·纳齐安"],place:"该撒利亚（今土耳其开塞利）",state:"罗马帝国与卡帕多西亚诸教会",sources:["巴西尔《书信集》与《长规》《短规》","额我略·纳齐安之讲辞与书信","该撒利亚城址与医舍遗构勘察之文"],tags:["病舍","修道规","慈善"]},related:[]},
  {id:"world--376--p01",track:"world",year:376,yearApprox:false,dim:"politics",weight:5,title:"哥特人渡多瑙内附",summary:"省吏纳其请而济其众，边民之寄遂为心腹之患。",detail:{background:"匈人西击，哥特诸部分裂而请附；省吏许其渡河，利其孳畜与丁壮。",process:"公元376年，弗里提格恩等率众请内附，廷许渡多瑙河，屯于色雷斯；然吏侵其粮、卖其老弱，饿殍与怨声俱起，传教之众亦杂其间。",impact:"未几有阿德里亚堡之败，哥特遂以盟军之名留于巴尔干，不复为罗马之臣；其族之分支后入意大利与高卢，为西国之大变。",figures:["弗里提格恩","瓦伦斯"],place:"多瑙河界与色雷斯",state:"罗马帝国与哥特诸部",sources:["阿米安努斯《罗马史》第三十一章","索佐门诺斯《教会史》","多瑙南岸与色雷斯之定居遗迹与钱币"],tags:["内附","多瑙河","哥特"]},related:[]},
  {id:"world--379--p01",track:"world",year:379,yearApprox:false,dim:"politics",weight:4,title:"狄奥多西受东方之任",summary:"边败之余，西方之君以西班牙之将为同治。",detail:{background:"阿德里亚堡之败后，巴尔干诸城被围，军府与近卫之众几于俱尽。",process:"公元379年1月，格拉提安召狄奥多西于其乡里，授以东方之任；乃募边民与部族之兵，以将佐分抚之，二年而后哥特定居之约成。",impact:"自是帝国东、西分立为常局，部族之兵入为军之骨干；380年之信理诏与381年之大会议，皆出其廷。",figures:["狄奥多西一世","格拉提安"],place:"君士坦丁堡与色雷斯军前",state:"罗马帝国",sources:["《晚期拉丁颂辞集》三八九、三九〇年之颂","佐西默斯《新史》第四卷","是朝东方诸铸监之钱币"],tags:["同治","部族兵","东方"]},related:[]},
  {id:"world--381--c01",track:"world",year:381,yearApprox:false,dim:"culture",weight:5,title:"君士坦丁堡之大会议",summary:"东方诸主重申尼西亚之信，新都之号次罗马。",detail:{background:"阿利乌之党与「体似」之说历五十余年不决，帝以会议欲一其论。",process:"公元381年，东方主教百五十余人会于君士坦丁堡，重申尼西亚之信辞，又定诸会之界与新都之秩；其论圣神一条，学界或谓成于此会，或谓至五世纪始定。",impact:"今东西诸会同诵之信经即此名，「次旧都」一条则为千余年两廷相争之根；会议之法亦成教会律例之祖。",figures:["狄奥多西一世","额我略·纳齐安","弗拉维安"],place:"君士坦丁堡",state:"罗马帝国与诸教会",sources:["381年会议之法条与信经（后世诸辑本）","索克拉底与索佐门诺斯《教会史》","会议签名主教之名录"],tags:["公会议","信经","两廷"]},related:[]},
  {id:"world--383--a01",track:"world",year:383,yearApprox:true,dim:"art",weight:2,title:"狄奥多西纪功柱与凯旋拱",summary:"为东边之捷与和议，两都并起图像之纪。",detail:{background:"狄奥多西以哥特之和与边功为业，依前朝之例请立纪功之象。",process:"约公元383至393年间，罗马大马路之凯旋拱告成，其面写战事与抚边之仪；君士坦丁堡之奥古斯泰昂也立柱，基刻其入都之礼。",impact:"两处浮雕为四世纪末军服、使节与朝仪图像之最要者；其式样并为后此之帝礼与凯旋所沿。",figures:["狄奥多西一世","阿卡狄乌斯"],place:"罗马与君士坦丁堡",state:"罗马帝国",sources:["狄奥多西纪功柱与凯旋拱浮雕之实测刊布","《晚期拉丁颂辞集》三八九、三九〇年之颂","是朝钱币与币铭"],tags:["纪功柱","浮雕","朝仪"]},related:[]},
  {id:"world--385--f01",track:"world",year:385,yearApprox:true,dim:"figure",weight:3,title:"哲罗姆去罗马而东隐",summary:"书翰之任随宫廷之变而解，遂率同伴入东方。",detail:{background:"罗马之教士与贵族交讼，教位之争未息；其庇护者既去，都中不可居。",process:"公元384或385年，哲罗姆辞罗马，与数同伴东行，后居叙利亚之旷野治修业，又延犹太之师授希伯来文字。",impact:"其离罗马以后之业皆基于东方之学：校经本、译新书，成后世拉丁教会之标准；其书信亦为一世行旅与教界之要料。",figures:["哲罗姆","保拉"],place:"罗马至叙利亚之道",state:"罗马帝国与诸教会",sources:["哲罗姆《书信集》","哲罗姆《名士传》","近代所辑哲罗姆年谱"],tags:["译经","隐修","东方之学"]},related:[]},
  {id:"world--386--c01",track:"world",year:386,yearApprox:false,dim:"culture",weight:3,title:"殉者之骸与米兰之抗",summary:"都城门内得二殉道者，会众据圣堂以拒宫命。",detail:{background:"宫廷之主要夺米兰一圣堂以奉其同宗，主教安布罗修斯拒不奉诏。",process:"公元386年，四旬节中会众据堂自守，宫军围之久之；未几于城门内古冢得二殉道者之骸，移葬新堂，众作颂以和之。",impact:"此为教会以民众与殉者之遗骸拒君命之著例；所谓「安布罗修斯之颂」亦由兹传于西方，礼乐之制随之以东渐。",figures:["安布罗修斯","瓦伦提尼安二世","尤斯提娜"],place:"米兰",state:"罗马帝国与意大利诸教会",sources:["安布罗修斯《书信集》","保利努斯《安布罗修斯传》","奥古斯丁《忏悔录》第九卷"],tags:["圣髑","礼乐","君教之争"]},related:[]},
  {id:"world--390--c01",track:"world",year:390,yearApprox:false,dim:"culture",weight:4,title:"帖撒罗尼迦之屠与君主之罚",summary:"竞技场血流之后，主教闭门而不许君入。",detail:{background:"该城之民以所爱之车技者被系而愤，杀镇将而暴其尸，朝议震怒。",process:"公元390年，帝纵军于该城之竞技场，据古典诸史所记死者数千人（其数互异，未可征信）；米兰主教安布罗修斯遂不许君入堂行礼，久之乃解。",impact:"此为教会之权绳君主之身之最著例，后世之君礼、悔罪与绝罚皆引为据；其往还之书与讲辞俱存。",figures:["狄奥多西一世","安布罗修斯"],place:"帖撒罗尼迦与米兰",state:"罗马帝国与诸教会",sources:["安布罗修斯《书信集》与讲辞","保利努斯《安布罗修斯传》","佐西默斯《新史》第四卷"],tags:["屠城","绝罚","君权"]},related:[]},
  {id:"world--391--f01",track:"world",year:391,yearApprox:false,dim:"figure",weight:3,title:"奥古斯丁受长老之职",summary:"以宾客之身见拥于会众之前，遂为讲经之师。",detail:{background:"希波之会缺讲经之人，众以新至之修辞师属望；其主教为之施按手之礼。",process:"公元391年，奥古斯丁于希波受长老之任，自此讲道、释经，并驳摩尼与多纳图之徒；五年后承其师之位为该城主教。",impact:"其一生之著述、书信与会议之文多始于此年；后世西方之恩典论、原罪说与教会之裁判，皆循其辙。",figures:["奥古斯丁","瓦莱里乌斯"],place:"希波（今阿尔及利亚安纳巴一带）",state:"罗马帝国与北非诸教会",sources:["奥古斯丁《忏悔录》","奥古斯丁《订过录》与《书信集》","其讲辞之辑本与近代年谱"],tags:["按立","释经","北非"]},related:[]},
  {id:"world--396--m01",track:"world",year:396,yearApprox:true,dim:"military",weight:4,title:"哥特之众掠伯罗奔尼撒",summary:"峡关不守，希腊诸城再入于部族兵之路。",detail:{background:"狄奥多西既崩，东方之廷以部族之兵守巴尔干；阿拉里克不受新君之抚。",process:"公元396至397年，阿拉里克率哥特之众入希腊与伯罗奔尼撒，科林斯、阿尔戈斯诸城被其兵；东廷水陆相拒，久之乃北去。",impact:"此事既见巴尔干之不可守，亦开哥特之众以战与和向西方索食之路；十余年而有罗马之劫，其势始于斯。",figures:["阿拉里克","欧特罗皮乌斯"],place:"希腊与伯罗奔尼撒",state:"东罗马帝国与哥特诸部",sources:["克劳狄亚努斯《论执政官之誉》诸篇","佐西默斯《新史》第五卷","科林斯与伯罗奔尼撒诸城毁层之考古报告"],tags:["哥特","巴尔干","毁城"]},related:[]},
{id:"world--402--p01",track:"world",year:402,yearApprox:false,dim:"politics",weight:4,title:"西廷移驻拉韦纳",summary:"霍诺留徙西方朝廷于拉韦纳，恃沼泽港垣以自固。",detail:{background:"罗马城无险可守，哥特屡入波河平原；拉韦纳四周沼泽、港垣复固，自奥古斯都以来为水军之屯。",process:"公元402年前后，霍诺留依斯提利科之护遂驻其城，宫廷、有司与诏令之署皆从之；《狄奥多西法典》所收西帝之敕，多出此城。",impact:"西廷去罗马而仰阿非利加之粮，元老院之权日轻；拉韦纳之四门与曲港，遂为五世纪西朝政令之枢。",figures:["霍诺留","斯提利科"],place:"拉韦纳（今意大利拉韦纳）",state:"罗马帝国西部",sources:["佐西默斯《新史》第五卷","《狄奥多西法典》所收霍诺留诸敕之题署","拉韦纳与克拉斯斯港之考古发掘报告"],tags:["拉韦纳","西廷","迁驻"]},related:[]},
{id:"world--405--c01",track:"world",year:405,yearApprox:true,dim:"culture",weight:3,title:"阿尔明尼亚字母之创",summary:"梅斯罗普造阿尔明尼亚字母，经文自此可以国语读。",detail:{background:"阿尔明尼亚素无文字，公文与读经皆假希腊、叙利亚、波斯之字；其国处罗马与波斯之间，教会欲自立门户。",process:"梅斯罗普·马什托茨得瓦拉姆沙普尔王与主教以撒格之助，往以得萨问学，归而造三十六字母，先译《箴言》数节，复西行君士坦丁堡具其器用，还而尽译新约；创字之年有二说（公元405或406年），其师科里翁所记亦经后人增补。",impact:"字母成而教父之书相继译出，阿尔明尼亚文学自此独立；其字至今为教会所用，亦为高加索诸文字之先型。",figures:["梅斯罗普·马什托茨","瓦拉姆沙普尔王","以撒格"],place:"阿尔明尼亚（今亚美尼亚与土耳其东北部）",state:"阿尔明尼亚王国",sources:["科里翁《梅斯罗普行传》","拉扎尔·帕尔佩齐《阿尔明尼亚史》","耶列温藏早期字母抄本之古文字学研究"],tags:["文字","译经","阿尔明尼亚"]},related:[]},
{id:"world--407--p01",track:"world",year:407,yearApprox:false,dim:"politics",weight:4,title:"不列颠军拥君与边省之失",summary:"岛上守军自立君士坦丁，渡海入高卢，不列颠遂绝。",detail:{background:"不列颠三度受蛮兵之掠而救不至，士卒不得赐；公元406年之乱后两度拥立，皆为其众所杀。",process:"公元407年，众拥君士坦丁为帝，率岛上之戎渡海入高卢，边境之兵尽从；未几据特里尔，与意大略之朝廷对峙。岛上自此不复受中央之令。",impact:"官守、钱粮皆绝，城市、浴场与田庄相继废坠；哲罗姆叹其本为富饶之地而今分于诸蛮，罗马之名惟存于圣徒之传。",figures:["君士坦丁三世","霍诺留","哲罗姆"],place:"不列颠与高卢（今英吉利海峡两岸）",state:"罗马帝国西部",sources:["佐西默斯《新史》第六卷","《君士坦丁堡执政官编年史》公元408年条","哲罗姆《编年史》与《书信集》"],tags:["不列颠","僭位","边省"]},related:[]},
{id:"world--408--p01",track:"world",year:408,yearApprox:false,dim:"politics",weight:4,title:"斯提利科被诛与蛮兵家属之戮",summary:"西朝之将被杀，意大略屠其家属，遗孤北走哥特。",detail:{background:"斯提利科以半出蛮族为西朝之师，连却哥特；与朝臣奥吕斯库斯不协，东廷又尝授阿拉里克以名位之分。",process:"公元408年八月，军中传其欲立己子，霍诺留下诏收之；斯氏匿于教堂，出而被杀。未几，意大略诸城尽屠留居之蛮兵妻属，其遗孤奔于阿拉里克。",impact:"西朝失最后能战之将。奔于哥特者，据佐西默斯所记有三万人；阿拉里克遂以其众索地于意大略。",figures:["斯提利科","霍诺留","阿拉里克","奥吕斯库斯"],place:"意大略北境（今帕维亚一带）",state:"罗马帝国西部",sources:["佐西默斯《新史》第五卷","奥林匹奥多鲁斯《历史》残篇（见佛提乌《书目》）","约达尼斯《哥特史》"],tags:["斯提利科","兵变","屠杀"]},related:[]},
{id:"world--410--d01",track:"world",year:410,yearApprox:false,dim:"disaster",weight:5,title:"西哥特掠罗马",summary:"阿拉里克因门之启而入罗马，三日纵掠，远近震动。",detail:{background:"罗马被围三载，台伯河之粮道断，城中饥疫并作；元老院自出求和，又尝立阿塔卢斯以抗霍诺留，皆不成。",process:"公元410年八月二十四日，萨拉里门夜为城中仆役所启，哥特入城，纵火三日，毁诸宅与城外教堂之周廊，掠器用而去。",impact:"哲罗姆闻讯，谓俘掠世界者今自见俘；异教者以此祸归咎新教，奥罗修斯乃作书辩之，谓祸不以信仰之异而加。",figures:["阿拉里克","哲罗姆","奥罗修斯"],place:"罗马（今意大利罗马）",state:"罗马帝国西部",sources:["佐西默斯《新史》第五卷","奥罗修斯《历史》第七卷","哲罗姆《书信集》中致阿革鲁奇亚之书","普罗柯比《哥特战史》第一卷"],tags:["罗马","劫掠","西哥特"]},related:[]},
{id:"world--411--i01",track:"world",year:411,yearApprox:false,dim:"institution",weight:3,title:"迦太基之大会与多纳图派之禁",summary:"两派主教对讼于公庭，官使定案，异派遂受放逐。",detail:{background:"北非教会自四世纪初裂为二，正统与多纳图派互讼于官府；其党有周行之僧，里境苦之。奥古斯丁主以辩论折其说。",process:"公元411年六月，两派各二百余主教会于迦太基之公厅，官使玛尔切利努斯主其议，连日三辩，多纳图派之案不能立；其秋，西廷以其拒命乃下严令，许以放逐。",impact:"大会之行状与判决之卷具存，为研究北非教会与文书之要料；多纳图派由是失法律之地，而里境之党争延至七世纪。",figures:["奥古斯丁","佩提利阿努斯","玛尔切利努斯"],place:"迦太基（今突尼斯东北）",state:"罗马帝国西部",sources:["《迦太基大会行状》（公元411年官录）","奥古斯丁驳佩提利阿努斯诸书","普西狄乌斯《奥古斯丁传》"],tags:["北非教会","会议","多纳图派"]},related:[]},
{id:"world--411--s01",track:"world",year:411,yearApprox:true,dim:"science",weight:3,title:"玛尔切卢斯辑药方",summary:"高卢贵臣辑希腊旧方为拉丁书，西部医学之仅存。",detail:{background:"拉丁之医学久衰，希腊方书非医者不能读；高卢之贵臣犹集古方，以备军旅与家疗之用。",process:"波尔多之玛尔切卢斯依其自署之执政官年号，书成于公元409年或411年，二说未定；其书以药石、草木、虫兽为次，多采希腊名家之说而参以里俗之验。",impact:"此书为五世纪拉丁药方之最大编，后世抄本赖之以传，加洛林时期之医抄多资焉；西部之药学赖以不坠。",figures:["玛尔切卢斯"],place:"波尔多（今法国波尔多）",state:"罗马帝国西部",sources:["玛尔切卢斯《论诸药之本性与功用》及其自署之年","老普林尼《自然史》诸药之目（其所本）","近世校勘刊本与语文学研究"],tags:["医学","药方","拉丁"]},related:[]},
{id:"world--418--i01",track:"world",year:418,yearApprox:false,dim:"institution",weight:4,title:"西哥特以同盟屯阿基坦",summary:"瓦利亚与君士坦提乌斯成约，受田输粮以为守。",detail:{background:"阿拉里克死，阿陶尔夫继之，携帝妹普拉齐狄娅转徙高卢南境；西朝不能战，惟以粮与名位相市。",process:"公元418年，瓦利亚与统兵之君士坦提乌斯成约，以其众为同盟，受田于阿基坦，岁输谷物以当赋；未几奉命往西班牙击汪达尔与阿兰。",impact:"以盟代守自此为西朝定制：蛮族以兵为官府之用，官府以税为蛮族之饷；数十年后图卢兹遂为西哥特之都。",figures:["瓦利亚","君士坦提乌斯","加拉·普拉齐狄娅"],place:"阿基坦（今法国南部）",state:"罗马帝国西部与西哥特",sources:["奥罗修斯《历史》书末致普劳斯佩尔书","普洛斯佩尔《编年史》","希达提乌斯《编年史》"],tags:["同盟","西哥特","赋谷"]},related:[]},
{id:"world--425--a01",track:"world",year:425,yearApprox:true,dim:"art",weight:3,title:"拉韦纳之十字与使徒马赛克",summary:"砖构小堂之穹顶以金片贴十字与使徒，像设定式。",detail:{background:"西廷既驻拉韦纳，皇室之施舍随之；罗马画室东来之后，砖构之十字堂虽小，而覆以金碧之片。",process:"世称普拉齐狄娅陵者，其主体成于公元425年前后，断代尚有前后之歧；三十字之穹顶各当一使徒，下作鹿与飞鸟就泉，石片厚薄不匀而斜插灰泥，借侧窗以生金影。",impact:"基督教像设之程式于焉大定：十字居中、使徒环立、牧者与群兽，历拜占庭而下及加洛林诸朝。",figures:["加拉·普拉齐狄娅"],place:"拉韦纳（今意大利拉韦纳）",state:"罗马帝国西部",sources:["普拉齐狄娅陵结构与马赛克层位之研究","阿涅卢斯《拉韦纳主教传》所记诸堂施舍","金片玻璃之材料与工艺分析"],tags:["马赛克","拉韦纳","陵堂"]},related:[]},
{id:"world--429--m01",track:"world",year:429,yearApprox:false,dim:"military",weight:3,title:"汪达尔渡海入北非",summary:"盖塞里克自西班牙渡海，进围希坡，粮道遂绝。",detail:{background:"汪达尔与阿兰在西班牙受西哥特之蹙；西朝之将内讧，海峡之守不复能支，遂招其众渡海。",process:"公元429年，盖塞里克率众自休达渡海而东，诸里境之城相继降；公元430年进围希坡，凡十四月而城陷。渡海之数，据普罗柯比所记为八万人，然并老弱言之。",impact:"阿非利加之粮自此不归罗马，西朝之脉遂断；希坡讲席与藏书四散，西部教义乃出于迦太基与罗马。",figures:["盖塞里克","波尼法爵","奥古斯丁"],place:"北非（今阿尔及利亚东北）",state:"罗马帝国西部与汪达尔",sources:["普罗柯比《汪达尔战史》第一卷","孔坦提乌斯《希坡的奥古斯丁传》","维托尔《阿非利加迫害史》"],tags:["汪达尔","渡海","围城"]},related:[]},
{id:"world--430--f01",track:"world",year:430,yearApprox:false,dim:"figure",weight:4,title:"奥古斯丁卒于希坡围中",summary:"围城未解而主教卒，遗命以书卷付教会，葬于希坡。",detail:{background:"希坡被围之际，奥古斯丁年七十有五，犹答书判疑，且辑《撤回之论》以订毕生之文。",process:"其友普西狄乌斯与安提阿之赫拉狄乌斯在侧；公元430年八月二十八日卒。遗命不陈葬物，惟以圣经与讲稿付其教会，葬于主座之堂。",impact:"其恩与意之辩定西方神学之纲；《天城》遂为劫后罗马之自解，中世纪拉丁教义多出于是。",figures:["奥古斯丁","普西狄乌斯","赫拉狄乌斯"],place:"希坡（今阿尔及利亚安纳巴附近）",state:"罗马帝国西部",sources:["普西狄乌斯《奥古斯丁传》并其《书目》","奥古斯丁《撤回之论》","希坡城址与拜占庭期重修之发掘报告"],tags:["奥古斯丁","遗命","教会"]},related:[]},
{id:"world--431--c01",track:"world",year:431,yearApprox:false,dim:"culture",weight:5,title:"以弗所之会与“诞神女”之号",summary:"区利罗先期开会，定玛利亚之号，废涅斯多略。",detail:{background:"亚历山大的区利罗与君士坦丁堡之长老涅斯多略争基督之称：谓一母者，谓二子者；书札往还，罗马主教亦与难。",process:"公元431年六月，二百余主教集以弗所；区利罗不等东方诸省之同僚而至，三集而断，定玛利亚为诞神女之号，斥涅斯多略不悛；东方主教继至，别立一会以废区利罗，朝廷遣使两问而后定其案。",impact:"会议之案卷与诸书札具存，为五世纪教义之枢；不肯奉定议之叙利亚诸师东走波斯，希腊之哲学与医书随之而东译。",figures:["区利罗","涅斯多略","策乐斯丁","狄奥多勒"],place:"以弗所（今土耳其塞尔丘克附近）",state:"罗马帝国东部",sources:["《以弗所会议记录》诸卷及所附书札","区利罗《十二难问》","索佐门《教会史》","普洛斯佩尔《编年史》"],tags:["会议","教义","以弗所"]},related:[]},
{id:"world--449--x01",track:"world",year:449,yearApprox:false,dim:"explore",weight:3,title:"普利斯库斯使于单于之庭",summary:"东廷使者亲见阿提拉之帐、宴次与虏人之叹。",detail:{background:"东廷岁输黄金以赂匈人，而边市与逃奴之讼不已；公元449年使团北赴其庭，因得目验其国俗。",process:"普利斯库斯自多瑙河北渡，历诸部之营，入单于之殿：木构三层，毡幕为厨；宴则以次而坐，歌者起咏先人之功；同席有被虏之罗马匠人，留不敢归。",impact:"其书残篇为述单于庭之唯一目验，后世所记阿提拉之形貌礼节多本之；数年后沙隆之战与西朝之亡，皆可见其端。",figures:["普利斯库斯","阿提拉"],place:"匈庭潘诺尼亚（今匈牙利东部蒂萨河流域）",state:"匈帝国与东罗马帝国",sources:["普利斯库斯《史》残篇（见十世纪《使节辑纂》）","《玛克西穆斯编年史》（都林）公元450年前后条","约达尼斯《哥特史》"],tags:["使节","匈人","目验"]},related:[]},
{id:"world--451--c01",track:"world",year:451,yearApprox:false,dim:"culture",weight:5,title:"迦克顿之会与二性之定",summary:"数百主教定一位二性之语，东方诸教会由是而裂。",detail:{background:"以弗所之会后一性之说大行；君士坦丁堡之长老尤台恩以基督一性聚徒，罗马主教利奥以书辩二性之别。",process:"公元451年秋，主教数百人集于迦克顿之堂，历二十余集；先阅利奥之书与区利罗之文，定一位二性之语，又改正典之条，升君士坦丁堡之座次于旧都之后。",impact:"定议成而东方教会裂为数支：叙利亚、阿尔明尼亚与埃及别立其座；教义之争与帝权相纠，历三百年不解。",figures:["利奥一世","马尔齐安","普尔喀里亚","阿纳托利乌斯"],place:"迦克顿（今土耳其伊斯坦布尔亚洲岸）",state:"东罗马帝国",sources:["《迦克顿会议记录》希腊与拉丁之辑本","利奥《致弗拉维安书》（所谓大卷）","马尔齐安与普尔喀里亚之敕及会后之诏"],tags:["会议","二性","迦克顿"]},related:[]},
{id:"world--452--m01",track:"world",year:452,yearApprox:false,dim:"military",weight:4,title:"阿提拉止于波河",summary:"匈军破北意诸城而与教宗相见，无故北还。",detail:{background:"阿提拉以求婚之故索意大略之半；公元450年后，逾阿尔卑斯入波河平原，诸城多降。",process:"公元452年春，其众毁阿奎莱亚等处而南，西帝遣使并教宗利奥往，相见于波河上游之滨（一说在明丘斯河畔）。议之辞无传，其众忽引而北归。",impact:"退师之因，古典归之教宗之劝，近世则推以军中疫与粮乏，二说并立。阿奎莱亚之民徙于潟湖，后世威尼斯托始焉。",figures:["阿提拉","利奥一世","阿维图斯"],place:"波河平原（今意大利北部）",state:"匈帝国与罗马帝国西部",sources:["普利斯库斯《史》残篇（见十世纪《使节辑纂》）","《高卢编年史》公元452年条","普洛斯佩尔《编年史》","《瓦勒西匿名编年史》"],tags:["匈","波河","退师"]},related:[]},
{id:"world--455--d01",track:"world",year:455,yearApprox:false,dim:"disaster",weight:4,title:"汪达尔劫罗马",summary:"盖塞里克由海路至城下，载皇妃与器物东归。",detail:{background:"西帝为厨官所杀，重臣彼得罗利乌斯迫娶皇妃；未几彼得罗利乌斯又为阿维杜斯所杀，城中无兵。",process:"公元455年六月，盖塞里克自海路至奥斯提亚，教宗利奥往请之，得免焚城与滥杀；凡十四日，宫中器物、金帛与皇妃二女皆载以去。",impact:"西朝之粮与赋本于阿非利加，今海路尽为汪达尔之有，罗马之粮用遂日蹙；旧族之产既竭，西朝之兵柄不复可振。",figures:["盖塞里克","利奥一世","彼得罗利乌斯","优多克西亚"],place:"罗马与奥斯提亚（今意大利）",state:"汪达尔王国与罗马帝国西部",sources:["普洛斯佩尔《编年史》续编","《瓦勒西匿名编年史》","普罗柯比《汪达尔战史》第一卷","北非与撒尔达尼亚汪达尔期层位之考古报告"],tags:["汪达尔","劫掠","粮道"]},related:[]},
{id:"world--457--i01",track:"world",year:457,yearApprox:false,dim:"institution",weight:3,title:"汪达尔王之教令",summary:"阿利乌之令下而天主教之主教见逐，堂产籍没。",detail:{background:"盖塞里克奉阿利乌之教，欲以一教之信固其国；天主之教之主教与教堂之产皆其所忌。",process:"公元457年四月，下令不许天主之教行按立之礼，以诸会堂归于己众；未几主教多人放逐于科西嘉与撒尔达尼亚，服矿役，其产籍没。",impact:"北非之教会组织散乱数十年，堂宇与田产之目为之一变；流亡者之书与殉者之名录，遂为拉丁教会之痛史。",figures:["盖塞里克","德奥格剌西亚斯","维托尔"],place:"迦太基与阿非利加诸城（今突尼斯一带）",state:"汪达尔王国",sources:["维托尔《阿非利加迫害史》第一卷所收王之敕文","同书所记诸主教流放之名录","普罗柯比《汪达尔战史》述其教禁"],tags:["教禁","放逐","阿利乌"]},related:[]},
{id:"world--468--m01",track:"world",year:468,yearApprox:false,dim:"military",weight:3,title:"拜占庭征迦太基之败",summary:"三路出师而伪降火发，舟舰焚尽，海权复归汪达尔。",detail:{background:"西帝安特米乌斯与东廷合谋复阿非利加；东廷以巨金聚兵，又以和婚绥汪达尔。",process:"公元468年三路出师：一自海路直薄迦太基，一自陆路起的黎波里，一自撒尔达尼亚；初胜而舍舟，进至距城数十里之地。汪达尔伪请降，以火船夜攻，焚其舟舰大半，诸将多死。",impact:"其费据后世所记以十万磅金计（其数或有夸）；东廷遂弃复阿非利加之谋，汪达尔之海权由是确立。",figures:["巴西利库斯","马尔切利努斯","盖塞里克","安特米乌斯"],place:"迦太基外海与北非沿岸（今突尼斯东北）",state:"东罗马帝国与汪达尔王国",sources:["普罗柯比《汪达尔战史》第一卷","《马尔切林努斯编年史》公元468年条","《约翰·尼基乌编年史》所记其役之费","迦太基遗址之五六世纪层位发掘"],tags:["海战","火船","远征"]},related:[]},
{id:"world--475--p01",track:"world",year:475,yearApprox:false,dim:"politics",weight:3,title:"末帝之立与兵权之寄",summary:"军帅奥列斯忒斯立其幼子为西帝，号出于兵手。",detail:{background:"西朝之兵权自里西美尔以来不出于朝而出于帅；东廷所立之帝与西朝之将互相废立。",process:"公元475年十月，奥列斯忒斯于拉韦纳立其幼子罗慕路斯为帝，众以奥古斯都勒戏之；其母之名见于器物，朝廷之文牒则但书父名。",impact:"西帝之号自此出于兵帅之手而不能自举；明年帅废，罗马之西遂不复有其帝。",figures:["奥列斯忒斯","罗慕路斯·奥古斯都勒","里西美尔","尤利乌斯·涅波斯"],place:"拉韦纳（今意大利拉韦纳）",state:"罗马帝国西部",sources:["《瓦勒西匿名编年史》","《马尔切林努斯编年史》公元475年条","意大利诸执政官纪年之残本","罗慕路斯期之钱与砖铭"],tags:["僭立","兵权","西朝"]},related:[]},
{id:"world--485--c01",track:"world",year:485,yearApprox:false,dim:"culture",weight:3,title:"普罗克洛斯卒与雅典学园",summary:"新柏拉图之集大成者殁于雅典，讲席犹盛而势将危。",detail:{background:"雅典之学园承叙利亚之传，以几何、历算与神术为业；其时学徒多自亚细亚与叙利亚来。",process:"公元485年四月，普罗克洛斯卒于雅典，其门人为之撰传；所著以一与多之阶释柏拉图诸篇，又为欧几里得之书作解；门人记其日课：晨祷、讲习、著述、祭献，未尝废也。",impact:"其学东传于以得萨与波斯诸师，希腊之自然哲学与医算之业赖以不坠；未及半世，雅典之讲席遂为时势所逼。",figures:["普罗克洛斯","马尔库斯","达玛修斯"],place:"雅典（今希腊雅典）",state:"东罗马帝国",sources:["马尔库斯《普罗克洛斯传》","普罗克洛斯《柏拉图之神学》与《蒂迈欧注》","雅典学园遗址与其讲学诸碑"],tags:["新柏拉图","学园","注疏"]},related:[]},
{id:"world--486--m01",track:"world",year:486,yearApprox:false,dim:"military",weight:4,title:"苏瓦松之役与罗马领地之亡",summary:"法兰克联军破西阿格里乌斯，两河之间遂易主。",detail:{background:"高卢北部自中央之命绝后，犹有一地以罗马之法自守，其主者西阿格里乌斯，诸部目为王；法兰克方并其邻。",process:"公元486年，克洛维与拉加哈尔率法兰克之众至苏瓦松，战于城北；西阿格里乌斯败走图卢兹，为西哥特王所执，交与法兰克，遂见杀。",impact:"塞纳与卢瓦尔之间归于法兰克，其国以罗马之产与教会之助而立；高卢之罗马自此惟存于堂宇与法文之中。",figures:["克洛维","西阿格里乌斯","拉加哈尔","阿拉里克二世"],place:"苏瓦松（今法国埃纳省）",state:"法兰克与残余之罗马领地",sources:["格里高利《法兰克人史》第二卷","《阿奎坦尼亚编年史》残篇","图尔奈希尔德里克一世墓出土器物与铭文"],tags:["法兰克","高卢","并土"]},related:[]},
{id:"world--489--m01",track:"world",year:489,yearApprox:false,dim:"military",weight:3,title:"东哥特奉诏征意大略",summary:"狄奥多里克以东廷之命率众入意，两载围拉韦纳。",detail:{background:"意大略自里西美尔死后帅臣相杀；东廷以奥多亚塞之自立为忧，乃以征讨之诏授东哥特之王。",process:"公元489年，狄奥多里克率哥特之众自莫西亚逾东阿尔卑斯而入，四战于伊松佐、维罗纳、阿达与拉韦纳之境；奥多亚塞退保其城，围凡两载。",impact:"哥特以东廷之命而治西朝之土，其二重之治自此而始：哥特有其兵，罗马存其法与元老院。",figures:["狄奥多里克","奥多亚塞","芝诺"],place:"意大略（今意大利北部）",state:"东罗马帝国与东哥特",sources:["《瓦勒西匿名编年史》","约达尼斯《哥特史》与《罗马志》","恩诺狄乌斯之书札与颂辞","拉韦纳与帕维亚之哥特期层位发掘"],tags:["东哥特","奉诏","围城"]},related:[]},
{id:"world--491--p01",track:"world",year:491,yearApprox:false,dim:"politics",weight:3,title:"阿纳斯塔修斯之立",summary:"老臣以皇后之助登东帝之位，誓不鬻官而省费。",detail:{background:"芝诺无嗣而崩，都中诸党相持；皇后与牧首立其老臣，年且七十，以其不涉党争而许之。",process:"公元491年四月，于君士坦丁堡受牧首尤福米乌斯之冠；其先辞故事之馈，誓不鬻官，又申先帝之信典而不改。",impact:"其治二十七年，以省费整税立东廷之府库，为后来查士丁尼之兵备与营造资其本；然其宗教之倾向卒启贵族之叛。",figures:["阿纳斯塔修斯","阿里阿德涅","尤福米乌斯"],place:"君士坦丁堡（今土耳其伊斯坦布尔）",state:"东罗马帝国",sources:["《马尔切林努斯编年史》公元491年条","约书亚·斯提利特《编年史》残篇","普罗柯比《秘史》述其库藏之金","君士坦丁堡牧首名录之辑本"],tags:["东廷","加冕","省费"]},related:[]},
{id:"world--494--c01",track:"world",year:494,yearApprox:false,dim:"culture",weight:3,title:"格拉西乌斯论两权",summary:"教宗复书东帝，谓圣权与王权并立而祭司责重。",detail:{background:"东帝以通函欲结东方之讼而不与罗马之教宗议，教宗不喜，乃以书自明其分。",process:"公元494年，教宗格拉西乌斯致书东帝，谓治理之权有二：教宗之圣权与君王之王权，而祭司于末日之审更为可畏；又谓此分之设本于人性之弱。",impact:"此书为西方两权之论最古之定式；后世教权与君权相角之辞多本其语，而同时之东廷未之深信。",figures:["格拉西乌斯","阿纳斯塔修斯","阿克基乌斯"],place:"罗马与君士坦丁堡",state:"罗马帝国东西两部与诸教会",sources:["《格拉西乌斯书信集》所收致东帝之书","《罗马教宗传》格拉西乌斯条","恩诺狄乌斯《驳尤提基安》与其书札"],tags:["教权","君权","书札"]},related:[]},
{id:"world--496--i01",track:"world",year:496,yearApprox:true,dim:"institution",weight:3,title:"勃艮第王法之辑",summary:"部族之赎罪金与田分之目，始著于成文之法。",detail:{background:"勃艮第人据罗讷河上流，罗马之法与部族之俗并行于一境，讼者无所取正。",process:"公元496年前后始辑《勃艮第王法》，以赎罪金、田分与证人之目著为条；其文屡经后王与诸主教增改，序言并称王与主教所定，故成书之年二说未一。",impact:"此为部族法与罗马地产相调之最古成文之一；高卢南部之赎刑、田分与证人之制，皆由是定其式。",figures:["贡多巴德","西吉斯蒙德"],place:"罗讷河上流（今法国里昂至日内瓦之间）",state:"勃艮第王国",sources:["《勃艮第王法》正文与诸王之序","同期《萨尔利法》与《西哥特王法》之对照写本","里昂诸教会会议记录"],tags:["部族法","赎金","田分"]},related:[]},
{id:"world--498--e01",track:"world",year:498,yearApprox:false,dim:"economy",weight:3,title:"东廷铜币之新分",summary:"四等大铜钱始铸，市肆之税并以巨金买废。",detail:{background:"东地之市井久苦于破分之铜钱与市肆之杂税；阿纳斯塔修斯既整府库，乃并改钱制。",process:"公元498年始铸四等大铜钱，背以字记其值（四十、二十、十、五之等），并以纪年与监造之名为识；未几以巨金买废市肆之税，令商人自输其所当。",impact:"自君士坦丁以来之钱制于焉一变，东地之零用与税算皆赖新钱；钱背之纪年与监名，遂为后世定年之据。",figures:["阿纳斯塔修斯"],place:"君士坦丁堡与东境诸铸坊（今土耳其、叙利亚与埃及）",state:"东罗马帝国",sources:["阿纳斯塔修斯期四等大铜钱之品与其背文","约安尼斯·利多斯《论官制》述其废市税","《马尔切林努斯编年史》公元498年条","安条克与以弗所之铸坊与市肆遗址"],tags:["币制","铜钱","税"]},related:[]},
];
